$t = array();
$t[1] = 'سُورَة الْقَلَم مَكِّيَّة فِي قَوْل الْحَسَن وَعِكْرِمَة وَعَطَاء وَجَابِر . وَقَالَ اِبْن عَبَّاس وَقَتَادَة : مِنْ أَوَّلهَا إِلَى قَوْله تَعَالَى : &quot; سَنَسِمُهُ عَلَى الْخُرْطُوم &quot; [الْقَلَم : 16 ] مَكِّيّ . وَمِنْ بَعْد ذَلِكَ إِلَى قَوْله تَعَالَى : &quot; أَكْبَر لَوْ كَانُوا يَعْلَمُونَ &quot; [ الْقَلَم : 33 ] مَدَنِيّ . وَمِنْ بَعْد ذَلِكَ إِلَى قَوْله : &quot; يَكْتُبُونَ &quot; [ الْقَلَم : 47 ] مَكِّيّ . وَمِنْ بَعْد ذَلِكَ إِلَى قَوْله تَعَالَى : &quot; مِنْ الصَّالِحِينَ &quot; [الْقَلَم : 50 ] مَدَنِيّ , وَمَا بَقِيَ مَكِّيّ ; قَالَهُ الْمَاوَرْدِيّ .

&quot; ن وَالْقَلَم &quot; أَدْغَمَ النُّون الثَّانِيَة فِي هِجَائِهَا فِي الْوَاو أَبُو بَكْر وَالْمُفَضَّل وَهُبَيْرَة وَوَرْش وَابْن مُحَيْصِن وَابْن عَامِر وَالْكِسَائِيّ وَيَعْقُوب . وَالْبَاقُونَ بِالْإِظْهَارِ . وَقَرَأَ عِيسَى بْن عُمَر بِفَتْحِهَا ; كَأَنَّهُ أَضْمَرَ فِعْلًا . وَقَرَأَ اِبْن عَبَّاس وَنَصْر وَابْن أَبِي إِسْحَاق بِكَسْرِهَا عَلَى إِضْمَار حَرْف , الْقَسَم . وَقَرَأَ هَارُون وَمُحَمَّد بْن السَّمَيْقَع بِضَمِّهَا عَلَى الْبِنَاء . وَاخْتُلِفَ فِي تَأْوِيله ; فَرَوَى مُعَاوِيَة بْن قُرَّة عَنْ أَبِيهِ يَرْفَعهُ إِلَى النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ : ( ن لَوْح مِنْ نُور ) . وَرَوَى ثَابِت الْبُنَانِيّ أَنَّ &quot; ن &quot; الدَّوَاة . وَقَالَهُ الْحَسَن وَقَتَادَة . وَرَوَى الْوَلِيد بْن مُسْلِم قَالَ : حَدَّثَنَا مَالِك بْن أَنَس عَنْ سُمَيّ مَوْلَى أَبِي بَكْر عَنْ أَبِي صَالِح السَّمَّان عَنْ أَبِي هُرَيْرَة قَالَ : سَمِعْت رَسُول اللَّه صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَقُول : ( أَوَّل مَا خَلَقَ اللَّه الْقَلَم ثُمَّ خَلَقَ النُّون وَهِيَ الدَّوَاة وَذَلِكَ قَوْل تَعَالَى : &quot; ن وَالْقَلَم &quot; ثُمَّ قَالَ لَهُ اُكْتُبْ قَالَ : وَمَا أَكْتُب قَالَ : مَا كَانَ وَمَا هُوَ كَائِن إِلَى يَوْم الْقِيَامَة مِنْ عَمَل أَوْ أَجَل أَوْ رِزْق أَوْ أَثَر فَجَرَى الْقَلَم بِمَا هُوَ كَائِن إِلَى يَوْم الْقِيَامَة - قَالَ - ثُمَّ خَتَمَ فَم الْقَلَم فَلَمْ يَنْطِق وَلَا يَنْطِق إِلَى يَوْم الْقِيَامَة . ثُمَّ خَلَقَ الْعَقْل فَقَالَ الْجَبَّار مَا خَلَقْت خَلْقًا أَعْجَبَ إِلَيَّ مِنْك وَعِزَّتِي وَجَلَالِي لَأُكْمِلَنَّك فِيمَنْ أَحْبَبْت وَلَأُنْقِصَنَّك فِيمَنْ أَبْغَضْت ) قَالَ : ثُمَّ قَالَ رَسُول اللَّه صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ : ( أَكْمَل النَّاس عَقْلًا أَطْوَعهمْ لِلَّهِ وَأَعْمَلهُمْ بِطَاعَتِهِ ) . وَعَنْ مُجَاهِد قَالَ : &quot; ن &quot; الْحُوت الَّذِي تَحْت الْأَرْض السَّابِعَة . قَالَ : &quot; وَالْقَلَم &quot; الَّذِي كُتِبَ بِهِ الذِّكْر . وَكَذَا قَالَ مُقَاتِل وَمُرَّة الْهَمْدَانِيّ وَعَطَاء الْخُرَاسَانِيّ وَالسُّدِّيّ وَالْكَلْبِيّ : إِنَّ النُّون هُوَ الْحُوت الَّذِي عَلَيْهِ الْأَرَضُونَ . وَرَوَى أَبُو ظَبْيَان عَنْ اِبْن عَبَّاس قَالَ : أَوَّل مَا خَلَقَ اللَّه الْقَلَم فَجَرَى بِمَا هُوَ كَائِن , ثُمَّ رَفَعَ بُخَار الْمَاء فَخَلَقَ مِنْهُ السَّمَاء , ثُمَّ خَلَقَ النُّون فَبَسَطَ الْأَرْض عَلَى ظَهْره , فَمَادَتْ الْأَرْض فَأُثْبِتَتْ بِالْجِبَالِ , وَإِنَّ الْجِبَال لَتَفْخَر عَلَى الْأَرْض . ثُمَّ قَرَأَ اِبْن عَبَّاس &quot; ن وَالْقَلَم &quot; الْآيَة . وَقَالَ الْكَلْبِيّ وَمُقَاتِل : اِسْمه الْبَهْمُوت . قَالَ الرَّاجِز : مَالِي أَرَاكُمْ كُلّكُمْ سُكُوتًا وَاَللَّه رَبِّي خَلَقَ الْبَهْمُوتَا وَقَالَ أَبُو الْيَقْظَان وَالْوَاقِدِيّ : ليوثا . وَقَالَ كَعْب : لوثوثا . وَقَالَ : بلهموثا . وَقَالَ كَعْب : إِنَّ إِبْلِيس تَغَلْغَلَ إِلَى الْحُوت الَّذِي عَلَى ظَهْره الْأَرَضُونَ فَوَسْوَسَ فِي قَلْبه , وَقَالَ : أَتَدْرِي مَا عَلَى ظَهْرك يَا لوثوثا مِنْ الدَّوَابّ وَالشَّجَر وَالْأَرَضِينَ وَغَيْرهَا , لَوْ لَفَظْتهمْ أَلْقَيْتهمْ عَنْ ظَهْرك أَجْمَع ; فَهَمَّ ليوثا أَنْ يَفْعَل ذَلِكَ , فَبَعَثَ اللَّه إِلَيْهِ دَابَّة فَدَخَلَتْ مَنْخِره وَوَصَلَتْ إِلَى دِمَاغه , فَضَجَّ الْحُوت إِلَى اللَّه عَزَّ وَجَلَّ مِنْهَا فَأَذِنَ اللَّه لَهَا فَخَرَجَتْ . قَالَ كَعْب : فَوَاَللَّهِ إِنَّهُ لَيَنْظُر إِلَيْهَا وَتَنْظُر إِلَيْهِ إِنْ هَمَّ بِشَيْءٍ مِنْ ذَلِكَ عَادَتْ كَمَا كَانَتْ . وَقَالَ الضَّحَّاك عَنْ اِبْن عَبَّاس : إِنَّ &quot; ن &quot; آخِر حَرْف مِنْ حُرُوف الرَّحْمَن . قَالَ : الر , وحم , ون ; الرَّحْمَن تَعَالَى مُتَقَطِّعَة . وَقَالَ اِبْن زَيْد : هُوَ قَسَم أَقْسَمَ تَعَالَى بِهِ . وَقَالَ اِبْن كَيْسَان : هُوَ فَاتِحَة السُّورَة . وَقِيلَ : اِسْم السُّورَة . وَقَالَ عَطَاء وَأَبُو الْعَالِيَة : هُوَ اِفْتِتَاح اِسْمه نَصِير وَنُور وَنَاصِر . وَقَالَ مُحَمَّد بْن كَعْب : أَقْسَمَ اللَّه تَعَالَى بِنَصْرِهِ لِلْمُؤْمِنِينَ ; وَهُوَ حَقّ . بَيَانه قَوْله تَعَالَى : &quot; وَكَانَ حَقًّا عَلَيْنَا نَصْر الْمُؤْمِنِينَ &quot; [ الرُّوم : 47 ] وَقَالَ جَعْفَر الصَّادِق : هُوَ نَهْر مِنْ أَنْهَار الْجَنَّة يُقَال لَهُ نُون . وَقِيلَ : هُوَ الْمَعْرُوف مِنْ حُرُوف الْمُعْجَم , لِأَنَّهُ لَوْ كَانَ غَيْر ذَلِكَ لَكَانَ مُعْرَبًا ; وَهُوَ اِخْتِيَار الْقُشَيْرِيّ أَبُو نَصْر عَبْد الرَّحِيم فِي تَفْسِيره . قَالَ : لِأَنَّ &quot; ن &quot; حَرْف لَمْ يُعْرَب , فَلَوْ كَانَ كَلِمَة تَامَّة أُعْرِبَ كَمَا أُعْرِبَ الْقَلَم , فَهُوَ إِذًا حَرْف هِجَاء كَمَا فِي سَائِر مَفَاتِيح السُّوَر . وَعَلَى هَذَا قِيلَ : هُوَ اِسْم السُّورَة , أَيْ هَذِهِ السُّورَة &quot; ن &quot; . ثُمَّ قَالَ : &quot; وَالْقَلَم &quot; أَقْسَمَ بِالْقَلَمِ لِمَا فِيهِ مِنْ الْبَيَان كَاللِّسَانِ ; وَهُوَ وَاقِع عَلَى كُلّ قَلَم مِمَّا يَكْتُب بِهِ مَنْ فِي السَّمَاء وَمَنْ فِي الْأَرْض ; وَمِنْهُ قَوْل أَبِي الْفَتْح الْبُسْتِيّ : إِذَا أَقْسَمَ الْأَبْطَال يَوْمًا بِسَيْفِهِمْ وَعَدُوّهُ مِمَّا يُكْسِب الْمَجْد وَالْكَرَم كَفَى قَلَم الْكُتَّاب عِزًّا وَرِفْعَة مَدَى الدَّهْر أَنَّ اللَّه أَقْسَمَ بِالْقَلَمِ وَلِلشُّعَرَاءِ فِي تَفْضِيل الْقَلَم عَلَى السَّيْف أَبْيَات كَثِيرَة ; مَا ذَكَرْنَاهُ أَعْلَاهَا . وَقَالَ اِبْن عَبَّاس : هَذَا قَسَم بِالْقَلَمِ الَّذِي خَلَقَهُ اللَّه ; فَأَمَرَهُ فَجَرَى بِكِتَابَةِ جَمِيع مَا هُوَ كَائِن إِلَى يَوْم الْقِيَامَة . قَالَ : وَهُوَ قَلَم مِنْ نُور طُوله كَمَا بَيْنَ السَّمَاء وَالْأَرْض . وَيُقَال : خَلَقَ اللَّه الْقَلَم ثُمَّ نَظَرَ إِلَيْهِ فَانْشَقَّ نِصْفَيْنِ ; فَقَالَ : اجْرِ ; فَقَالَ : يَا رَبّ بِمَ أَجْرِي ؟ قَالَ بِمَا هُوَ كَائِن إِلَى يَوْم الْقِيَامَة ; فَجَرَى عَلَى اللَّوْح الْمَحْفُوظ . وَقَالَ الْوَلِيد بْن عُبَادَة بْن الصَّامِت : أَوْصَانِي أَبِي عِنْد مَوْته فَقَالَ : يَا بُنَيّ , اِتَّقِ اللَّه , وَاعْلَمْ أَنَّك لَنْ تَتَّقِي وَلَنْ تَبْلُغ الْعِلْم حَتَّى تُؤْمِن بِاَللَّهِ وَحْده , وَالْقَدَر خَيْره وَشَرّه , سَمِعْت النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَقُول : ( إِنَّ أَوَّل مَا خَلَقَ اللَّه الْقَلَم فَقَالَ لَهُ اُكْتُبْ فَقَالَ يَا رَبّ وَمَا أَكْتُب فَقَالَ اُكْتُبْ الْقَدَر فَجَرَى الْقَلَم فِي تِلْكَ السَّاعَة بِمَا كَانَ وَمَا هُوَ كَائِن إِلَى الْأَبَد ) وَقَالَ اِبْن عَبَّاس : أَوَّل مَا خَلَقَ اللَّه الْقَلَم فَأَمَرَهُ أَنْ يَكْتُب مَا هُوَ كَائِن ; فَكَتَبَ فِيمَا كَتَبَ &quot; تَبَّتْ يَدَا أَبِي لَهَب &quot; [ الْمَسَد : 1 ] . وَقَالَ قَتَادَة : الْقَلَم نِعْمَة مِنْ اللَّه تَعَالَى عَلَى عِبَاده . قَالَ غَيْره : فَخَلَقَ اللَّه الْقَلَم الْأَوَّل فَكَتَبَ مَا يَكُون فِي الذِّكْر وَوَضَعَهُ عِنْده فَوْق عَرْشه , ثُمَّ خَلَقَ الْقَلَم الثَّانِي لِيَكْتُب بِهِ فِي الْأَرْض ; عَلَى مَا يَأْتِي بَيَانه فِي سُورَة &quot; اِقْرَأْ بِاسْمِ رَبّك &quot; [ الْعَلَق : 1 ] .

أَيْ وَمَا يَكْتُبُونَ . يُرِيد الْمَلَائِكَة يَكْتُبُونَ أَعْمَال بَنِي آدَم ; قَالَهُ اِبْن عَبَّاس : وَقِيلَ : وَمَا يَكْتُبُونَ أَيْ النَّاس وَيَتَفَاهَمُونَ بِهِ . وَقَالَ اِبْن عَبَّاس : وَمَعْنَى &quot; وَمَا يَسْطُرُونَ &quot; وَمَا يَعْلَمُونَ . و &quot; مَا &quot; مَوْصُولَة أَوْ مَصْدَرِيَّة ; أَيْ وَمَسْطُورَاتهمْ أَوْ وَسَطْرهمْ , وَيُرَاد بِهِ كُلّ مَنْ يُسَطِّر أَوْ الْحَفَظَة ; عَلَى الْخِلَاف .';
$t[2] = 'هَذَا جَوَاب الْقَسَم وَهُوَ نَفْي , وَكَانَ الْمُشْرِكُونَ يَقُولُونَ لِلنَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ إِنَّهُ مَجْنُون , بِهِ شَيْطَان . وَهُوَ قَوْلهمْ : &quot; يَا أَيّهَا الَّذِي نُزِّلَ عَلَيْهِ الذِّكْر إِنَّك لَمَجْنُون &quot; [ الْحِجْر : 6 ] فَأَنْزَلَ اللَّه تَعَالَى رَدًّا عَلَيْهِمْ وَتَكْذِيبًا لِقَوْلِهِمْ { مَا أَنْتَ بِنِعْمَةِ رَبّك بِمَجْنُونٍ &quot; أَيْ بِرَحْمَةِ رَبّك . وَالنِّعْمَة هَاهُنَا الرَّحْمَة . وَيَحْتَمِل ثَانِيًا - أَنَّ النِّعْمَة هَاهُنَا قَسَم ; وَتَقْدِيره : مَا أَنْتَ وَنِعْمَة رَبّك بِمَجْنُونٍ ; لِأَنَّ الْوَاو وَالْبَاء مِنْ حُرُوف الْقَسَم . وَقِيلَ هُوَ كَمَا تَقُول : مَا أَنْتَ بِمَجْنُونٍ , وَالْحَمْد لِلَّهِ . وَقِيلَ : مَعْنَاهُ مَا أَنْتَ بِمَجْنُونٍ , وَالنِّعْمَة لِرَبِّك ; كَقَوْلِهِمْ : سُبْحَانك اللَّهُمَّ وَبِحَمْدِك ; أَيْ وَالْحَمْد لِلَّهِ . وَمِنْهُ قَوْل لَبِيد : وَأُفْرِدْت فِي الدُّنْيَا بِفَقْدِ عَشِيرَتِي وَفَارَقَنِي جَار بِأَرْبَد نَافِع أَيْ وَهُوَ أَرْبَد . وَقَالَ النَّابِغَة : لَمْ يُحْرَمُوا حُسْن الْغِذَاء وَأُمّهمْ طَفَحَتْ عَلَيْك بِنَاتِقٍ مِذْكَار أَيْ هُوَ نَاتِق . وَالْبَاء فِي &quot; بِنِعْمَةِ رَبّك &quot; مُتَعَلِّقَة &quot; بِمَجْنُونٍ &quot; مَنْفِيًّا ; كَمَا يَتَعَلَّق بِغَافِلٍ مُثْبَتًا . كَمَا فِي قَوْلِك : أَنْتَ بِنِعْمَةِ رَبّك غَافِل . وَمَحَلّه النَّصْب عَلَى الْحَال ; كَأَنَّهُ قَالَ : مَا أَنْتَ بِمَجْنُونٍ مُنْعَمًا عَلَيْك بِذَلِكَ .';
$t[3] = 'أَيْ ثَوَابًا عَلَى مَا تَحَمَّلْت مِنْ أَثْقَال النُّبُوَّة .

أَيْ غَيْر مَقْطُوع وَلَا مَنْقُوص ; يُقَال : مَنَنْت الْحَبْل إِذَا قَطَعْته . وَحَبْل مَنِين إِذَا كَانَ غَيْر مَتِين . قَالَ الشَّاعِر : غُبْسًا كَوَاسِب لَا يُمَنّ طَعَامهَا أَيْ لَا يُقْطَع . وَقَالَ مُجَاهِد : &quot; غَيْر مَمْنُون &quot; مَحْسُوب . الْحَسَن : &quot; غَيْر مَمْنُون &quot; غَيْر مُكَدَّر بِالْمَنِّ . الضَّحَّاك : أَجْرًا بِغَيْرِ عَمَل . وَقِيلَ : غَيْر مُقَدَّر وَهُوَ التَّفَضُّل ; لِأَنَّ الْجَزَاء مُقَدَّر وَالتَّفَضُّل غَيْر مُقَدَّر ; ذَكَرَهُ الْمَاوَرْدِيّ , وَهُوَ مَعْنَى قَوْل مُجَاهِد .';
$t[4] = 'فِيهِ مَسْأَلَتَانِ : الْأُولَى : قَوْله تَعَالَى : &quot; وَإِنَّك لَعَلَى خُلُق عَظِيم &quot; قَالَ اِبْن عَبَّاس وَمُجَاهِد : عَلَى خُلُق , عَلَى دِين عَظِيم مِنْ الْأَدْيَان , لَيْسَ دِين أَحَبّ إِلَى اللَّه تَعَالَى وَلَا أَرْضَى عِنْده مِنْهُ . وَفِي صَحِيح مُسْلِم عَنْ عَائِشَة أَنَّ خُلُقه كَانَ الْقُرْآن . وَقَالَ عَلِيّ رَضِيَ اللَّه عَنْهُ وَعَطِيَّة : هُوَ أَدَب الْقُرْآن . وَقِيلَ : هُوَ رِفْقه بِأُمَّتِهِ وَإِكْرَامه إِيَّاهُمْ . وَقَالَ قَتَادَة : هُوَ مَا كَانَ يَأْتَمِر بِهِ مِنْ أَمْر اللَّه وَيَنْتَهِي عَنْهُ مِمَّا نَهَى اللَّه عَنْهُ . وَقِيلَ : أَيْ إِنَّك عَلَى طَبْع كَرِيم . الْمَاوَرْدِيّ : وَهُوَ الظَّاهِر . وَحَقِيقَة الْخُلُق فِي اللُّغَة : هُوَ مَا يَأْخُذ بِهِ الْإِنْسَان نَفْسه مِنْ الْأَدَبِ يُسَمَّى خُلُقًا ; لِأَنَّهُ يَصِير كَالْخِلْقَةِ فِيهِ . وَأَمَّا مَا طُبِعَ عَلَيْهِ مِنْ الْأَدَب فَهُوَ الْخِيم ( بِالْكَسْرِ ) : السَّجِيَّة وَالطَّبِيعَة , لَا وَاحِد لَهُ مِنْ لَفْظه . وَخِيم : اِسْم جَبَل . فَيَكُون الْخُلُق الطَّبْع الْمُتَكَلَّف . وَالْخِيم الطَّبْع الْغَرِيزِيّ . وَقَدْ أَوْضَحَ الْأَعْشَى ذَلِكَ فِي شِعْره فَقَالَ : وَإِذَا ذُو الْفُضُول ضَنَّ عَلَى الْمَوْلَى وَعَادَتْ لِخِيمِهَا الْأَخْلَاق أَيْ رَجَعَتْ الْأَخْلَاق إِلَى طَبَائِعهَا . قُلْت : مَا ذَكَرْته عَنْ عَائِشَة فِي صَحِيح مُسْلِم أَصَحّ الْأَقْوَال . وَسُئِلْت أَيْضًا عَنْ خُلُقه عَلَيْهِ السَّلَام ; فَقَرَأَتْ &quot; قَدْ أَفْلَحَ الْمُؤْمِنُونَ &quot; [ الْمُؤْمِنُونَ : 1 ] إِلَى عَشْر آيَات , وَقَالَتْ : مَا كَانَ أَحَد أَحْسَنَ خُلُقًا مِنْ رَسُول اللَّه صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ , مَا دَعَاهُ أَحَد مِنْ الصَّحَابَة وَلَا مِنْ أَهْل بَيْته إِلَّا قَالَ لَبَّيْكَ , وَلِذَلِكَ قَالَ اللَّه تَعَالَى &quot; وَإِنَّك لَعَلَى خُلُق عَظِيم &quot; . وَلَمْ يُذْكَر خُلُق مَحْمُود إِلَّا وَكَانَ لِلنَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ مِنْهُ الْحَظّ الْأَوْفَر . وَقَالَ الْجُنَيْد : سُمِّيَ خُلُقه عَظِيمًا لِأَنَّهُ لَمْ تَكُنْ لَهُ هِمَّة سِوَى اللَّه تَعَالَى . وَقِيلَ سُمِّيَ خُلُقه عَظِيمًا لِاجْتِمَاعِ مَكَارِم الْأَخْلَاق فِيهِ ; يَدُلّ عَلَيْهِ قَوْله عَلَيْهِ السَّلَام : ( إِنَّ اللَّه بَعَثَنِي لِأُتِمّ مَكَارِم الْأَخْلَاق ) . وَقِيلَ : لِأَنَّهُ اِمْتَثَلَ تَأْدِيب اللَّه تَعَالَى إِيَّاهُ بِقَوْلِهِ تَعَالَى : &quot; خُذْ الْعَفْو وَأَمْر بِالْعُرْفِ وَأَعْرِضْ عَنْ الْجَاهِلِينَ &quot; [ الْأَعْرَاف : 199 ] . وَقَدْ رُوِيَ عَنْهُ عَلَيْهِ السَّلَام أَنَّهُ قَالَ : ( أَدَّبَنِي رَبِّي تَأْدِيبًا حَسَنًا إِذْ قَالَ : &quot; خُذْ الْعَفْو وَأْمُر بِالْعُرْفِ وَأَعْرِضْ عَنْ الْجَاهِلِينَ &quot; [الْأَعْرَاف : 199 ] فَلَمَّا قَبِلْت ذَلِكَ مِنْهُ قَالَ : &quot; إِنَّك لَعَلَى خُلُق عَظِيم &quot; .

الثَّانِيَة : رَوَى التِّرْمِذِيّ عَنْ أَبِي ذَرّ قَالَ : قَالَ رَسُول اللَّه صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ : ( اِتَّقِ اللَّه حَيْثُمَا كُنْت وَأَتْبِعْ السَّيِّئَة الْحَسَنَة تَمْحُهَا وَخَالِق النَّاس بِخُلُقِ حَسَنٍ ) . قَالَ حَدِيث حَسَن صَحِيح . وَعَنْ أَبِي الدَّرْدَاء أَنَّ النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ : ( مَا شَيْء أَثْقَل فِي مِيزَان الْمُؤْمِن يَوْم الْقِيَامَة مِنْ خُلُق حَسَن وَإِنَّ اللَّه تَعَالَى لَيُبْغِض الْفَاحِش الْبَذِيء ) . قَالَ : حَدِيث حَسَن صَحِيح . وَعَنْهُ قَالَ : سَمِعْت النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَقُول : ( مَا مِنْ شَيْء يُوضَع فِي الْمِيزَان أَثْقَل مِنْ حُسْن الْخُلُق وَإِنَّ صَاحِب حُسْن الْخُلُق لَيَبْلُغ بِهِ دَرَجَة صَاحِب الصَّلَاة وَالصَّوْم ) . قَالَ : حَدِيث غَرِيب مِنْ هَذَا الْوَجْه . وَعَنْ أَبِي هُرَيْرَة قَالَ : سُئِلَ رَسُول اللَّه صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ عَنْ أَكْثَر مَا يُدْخِل النَّاس الْجَنَّة ؟ فَقَالَ : ( تَقْوَى اللَّه وَحُسْن الْخُلُق ) . وَسُئِلَ عَنْ أَكْثَر مَا يُدْخِل النَّاس النَّار ؟ فَقَالَ : ( الْفَم وَالْفَرْج ) قَالَ : هَذَا حَدِيث صَحِيح غَرِيب . وَعَنْ عَبْد اللَّه بْن الْمُبَارَك أَنَّهُ وَصَفَ حُسْن الْخُلُق فَقَالَ : هُوَ بَسْط الْوَجْه , وَبَذْل الْمَعْرُوف , وَكَفّ الْأَذَى . وَعَنْ جَابِر أَنَّ رَسُول اللَّه صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ : ( إِنَّ مِنْ أَحَبّكُمْ إِلَيَّ وَأَقْرَبكُمْ مِنِّي مَجْلِسًا يَوْم الْقِيَامَة أَحْسَنكُمْ أَخْلَاقًا - قَالَ - وَإِنَّ أَبْغَضكُمْ إِلَيَّ وَأَبْعَدكُمْ مِنِّي مَجْلِسًا يَوْم الْقِيَامَة الثَّرْثَارُونَ وَالْمُتَشَدِّقُونَ وَالْمُتَفَيْهِقُونَ ) . قَالُوا : يَا رَسُول اللَّه , قَدْ عَلِمْنَا الثَّرْثَارُونَ وَالْمُتَشَدِّقُونَ , فَمَا الْمُتَفَيْهِقُونَ ؟ قَالَ : ( الْمُتَكَبِّرُونَ ) . قَالَ : وَفِي الْبَاب عَنْ أَبِي هُرَيْرَة وَهَذَا حَدِيث حَسَن غَرِيب مِنْ هَذَا الْوَجْه .';
$t[5] = 'قَالَ اِبْن عَبَّاس : مَعْنَاهُ فَسَتَعْلَمُ وَيَعْلَمُونَ يَوْم الْقِيَامَة . وَقِيلَ : فَسَتَرَى وَيَرَوْنَ يَوْم الْقِيَامَة حِين يَتَبَيَّن الْحَقّ وَالْبَاطِل .';
$t[6] = 'الْبَاء زَائِدَة ; أَيْ فَسَتُبْصِرُ وَيُبْصِرُونَ أَيّكُمْ الْمَفْتُون . أَيْ الَّذِي فُتِنَ بِالْجُنُونِ ; كَقَوْلِهِ تَعَالَى : &quot; تَنْبُت بِالدُّهْنِ &quot; [ الْمُؤْمِنُونَ : 20 ] و &quot; يَشْرَب بِهَا عِبَاد اللَّه &quot; [ الْإِنْسَان : 6 ] . وَهَذَا قَوْل قَتَادَة وَأَبِي عُبَيْد وَالْأَخْفَش . وَقَالَ الرَّاجِز : نَحْنُ بَنُو جَعْدَة أَصْحَاب الْفَلَج نَضْرِب بِالسَّيْفِ وَنَرْجُو بِالْفَرَجِ وَقِيلَ : الْبَاء لَيْسَتْ بِزَائِدَةٍ ; وَالْمَعْنَى : &quot; بِأَيِّكُمْ الْمَفْتُون &quot; أَيْ الْفِتْنَة . وَهُوَ مَصْدَر عَلَى وَزْن الْمَفْعُول , وَيَكُون مَعْنَاهُ الْفُتُون ; كَمَا قَالُوا : مَا لِفُلَانٍ مَجْلُود وَلَا مَعْقُول ; أَيْ عَقْل وَلَا جَلَادَة . وَقَالَهُ الْحَسَن وَالضَّحَّاك وَابْن عَبَّاس . وَقَالَ الرَّاعِي : حَتَّى إِذَا لَمْ يَتْرُكُوا لِعِظَامِهِ لَحْمًا وَلَا لِفُؤَادِهِ مَعْقُولًا أَيْ عَقْلًا . وَقِيلَ فِي الْكَلَام تَقْدِير حَذْف مُضَاف ; وَالْمَعْنَى : بِأَيِّكُمْ فِتْنَة الْمَفْتُون . وَقَالَ الْفَرَّاء : الْبَاء بِمَعْنَى فِي ; أَيْ فَسَتُبْصِرُ وَيُبْصِرُونَ فِي أَيّ الْفَرِيقَيْنِ الْمَجْنُون ; أَبِالْفِرْقَةِ الَّتِي أَنْتَ فِيهَا مِنْ الْمُؤْمِنِينَ أَمْ بِالْفِرْقَةِ الْأُخْرَى . وَالْمَفْتُون : الْمَجْنُون الَّذِي فَتَنَهُ الشَّيْطَان . وَقِيلَ : الْمَفْتُون الْمُعَذَّب . مِنْ قَوْل الْعَرَب : فَتَنْت الذَّهَب بِالنَّارِ إِذَا حَمَّيْتَهُ . وَمِنْهُ قَوْله تَعَالَى : &quot; يَوْم هُمْ عَلَى النَّار يُفْتَنُونَ &quot; [ الذَّارِيَات : 13 ] أَيْ يُعَذَّبُونَ . وَمُعْظَم السُّورَة نَزَلَتْ فِي الْوَلِيد بْن الْمُغِيرَة وَأَبِي جَهْل . وَقِيلَ : الْمَفْتُون هُوَ الشَّيْطَان ; لِأَنَّهُ مَفْتُون فِي دِينه . وَكَانُوا يَقُولُونَ : إِنَّ بِهِ شَيْطَانًا , وَعَنَوْا بِالْمَجْنُونِ هَذَا ; فَقَالَ اللَّه تَعَالَى : فَسَيَعْلَمُونَ غَدًا بِأَيِّهِمْ الْمَجْنُون ; أَيْ الشَّيْطَان الَّذِي يَحْصُل مِنْ مَسّه الْجُنُون وَاخْتِلَاط الْعَقْل .';
$t[7] = 'أَيْ إِنَّ اللَّه هُوَ الْعَالِم بِمَنْ حَادَ عَنْ دِينه .

أَيْ الَّذِينَ هُمْ عَلَى الْهُدَى فَيُجَازِي كُلًّا غَدًا بِعَمَلِهِ .';
$t[8] = 'نَهَاهُ عَنْ مُمَايَلَةِ الْمُشْرِكِينَ ; وَكَانُوا يَدْعُونَهُ إِلَى أَنْ يَكُفّ عَنْهُمْ لِيَكُفُّوا عَنْهُ , فَبَيَّنَ اللَّه تَعَالَى أَنَّ مُمَايَلَتَهُمْ كُفْر . وَقَالَ تَعَالَى : &quot; وَلَوْلَا أَنْ ثَبَّتْنَاك لَقَدْ كِدْت تَرْكَن إِلَيْهِمْ شَيْئًا قَلِيلًا &quot; [ الْإِسْرَاء : 74 ] . وَقِيلَ : أَيْ فَلَا تُطِعْ الْمُكَذِّبِينَ فِيمَا دَعَوْك إِلَيْهِ مِنْ دِينهمْ الْخَبِيث . نَزَلْت فِي مُشْرِكِي قُرَيْش حِينَ دَعَوْهُ إِلَى دِين آبَائِهِ .';
$t[9] = 'قَالَ اِبْن عَبَّاس وَعَطِيَّة وَالضَّحَّاك وَالسُّدِّيّ : وَدُّوا لَوْ تَكْفُر فَيَتَمَادَوْنَ عَلَى كُفْرهمْ . وَعَنْ اِبْن عَبَّاس أَيْضًا : وَدُّوا لَوْ تُرَخِّص لَهُمْ فَيُرَخِّصُونَ لَك . وَقَالَ الْفَرَّاء وَالْكَلْبِيّ : لَوْ تَلِينَ فَيَلِينُونَ لَك . وَالْإِدْهَان : التَّلْيِين لِمَنْ لَا يَنْبَغِي لَهُ التَّلْيِين ; قَالَهُ الْفَرَّاء . وَقَالَ مُجَاهِد : الْمَعْنَى وَدُّوا لَوْ رَكَنْت إِلَيْهِمْ وَتَرَكْت الْحَقّ فَيُمَالِئُونَك . وَقَالَ الرَّبِيع بْن أَنَس : وَدُّوا لَوْ تَكْذِب فَيَكْذِبُونَ . وَقَالَ قَتَادَة : وَدُّوا لَوْ تَذْهَب عَنْ هَذَا الْأَمْر فَيَذْهَبُونَ مَعَك . الْحَسَن : وَدُّوا لَوْ تُصَانِعهُمْ فِي دِينِك فَيُصَانِعُونَك فِي دِينهمْ . وَعَنْهُ أَيْضًا : وَدُّوا لَوْ تَرْفُض بَعْض أَمْرك فَيَرْفُضُونَ بَعْض أَمْرهمْ . زَيْد بْن أَسْلَمَ : لَوْ تُنَافِق وَتُرَائِي فَيُنَافِقُونَ وَيُرَاءُونَ . وَقِيلَ : وَدُّوا لَوْ تَضْعُف فَيَضْعُفُونَ ; قَالَهُ أَبُو جَعْفَر . وَقِيلَ : وَدُّوا لَوْ تُدَاهِن فِي دِينِك فَيُدَاهِنُونَ فِي أَدْيَانهمْ ; قَالَهُ الْقُتَبِيّ . وَعَنْهُ : طَلَبُوا مِنْهُ أَنْ يَعْبُد آلِهَتهمْ مُدَّة وَيَعْبُدُوا إِلَهه مُدَّة . فَهَذِهِ اِثْنَا عَشَرَ قَوْلًا . اِبْن الْعَرَبِيّ : ذَكَرَ الْمُفَسِّرُونَ فِيهَا نَحْو عَشَرَة أَقْوَال كُلّهَا دَعَاوَى عَلَى اللُّغَة وَالْمَعْنَى . أَمْثَلهَا قَوْلهمْ : وَدُّوا لَوْ تَكْذِب فَيَكْذِبُونَ , وَدُّوا لَوْ تَكْفُر فَيَكْفُرُونَ . قُلْت : كُلّهَا إِنْ شَاءَ اللَّه تَعَالَى صَحِيحَة عَلَى مُقْتَضَى اللُّغَة وَالْمَعْنَى ; فَإِنَّ الْإِدْهَان : اللِّين وَالْمُصَانَعَة . وَقِيلَ : مُجَامَلَة الْعَدُوّ مُمَايَلَتُهُ . وَقِيلَ : الْمُقَارَبَة فِي الْكَلَام وَالتَّلْيِين فِي الْقَوْل . قَالَ الشَّاعِر : لَبَعْض الْغَشْم أَحْزَم فِي أُمُور تَنُوبُك مِنْ مُدَاهَنَة الْعِدَه وَقَالَ الْمُفَضَّل : النِّفَاق وَتَرْك الْمُنَاصَحَة . فَهِيَ عَلَى هَذَا الْوَجْه مَذْمُومَة , وَعَلَى الْوَجْه الْأَوَّل غَيْر مَذْمُومَة , وَكُلّ شَيْء مِنْهَا لَمْ يَكُنْ . قَالَ الْمُبَرِّد : يُقَال أَدْهَنَ فِي دِينه وَدَاهَنَ فِي أَمْره ; أَيْ خَانَ فِيهِ وَأَظْهَرَ خِلَاف مَا يُضْمِر . وَقَالَ قَوْم : دَاهَنْت بِمَعْنَى وَارَيْت , وَأَدْهَنْت بِمَعْنَى غَشَشْت ; قَالَ الْجَوْهَرِيّ . وَقَالَ : &quot; فَيُدْهِنُونَ &quot; فَسَاقَهُ عَلَى الْعَطْف , وَلَوْ جَاءَ بِهِ جَوَاب النَّهْي لَقَالَ فَيُدْهِنُوا . وَإِنَّمَا أَرَادَ : إِنْ تَمَنَّوْا لَوْ فَعَلْت فَيَفْعَلُونَ مِثْل فِعْلِك ; عَطْفًا لَا جَزَاء عَلَيْهِ وَلَا مُكَافَأَة , وَإِنَّمَا هُوَ تَمْثِيل وَتَنْظِير .';
$t[10] = 'يَعْنِي الْأَخْنَس بْن شَرِيق ; فِي قَوْل الشَّعْبِيّ وَالسُّدِّيّ وَابْن إِسْحَاق . وَقِيلَ : الْأَسْوَد بْن عَبْد يَغُوث , أَوْ عَبْد الرَّحْمَن بْن الْأَسْوَد ; قَالَهُ مُجَاهِد . وَقِيلَ : الْوَلِيد بْن الْمُغِيرَة , عَرَضَ عَلَى النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ مَالًا وَحَلَفَ أَنْ يُعْطِيه إِنْ رَجَعَ عَنْ دِينه ; قَالَهُ مُقَاتِل . وَقَالَ اِبْن عَبَّاس : هُوَ أَبُو جَهْل بْن هِشَام . وَالْحَلَّاف : الْكَثِير الْحَلِف . وَالْمَهِين : الضَّعِيف الْقَلْب ; عَنْ مُجَاهِد . اِبْن عَبَّاس : الْكَذَّاب . وَالْكَذَّاب مَهِين . وَقِيلَ : الْمِكْثَار فِي الشَّرّ ; قَالَهُ الْحَسَن وَقَتَادَة . وَقَالَ الْكَلْبِيّ : الْمَهِين الْفَاجِر الْعَاجِز . وَقِيلَ : مَعْنَاهُ الْحَقِير عِنْد اللَّه . وَقَالَ اِبْن شَجَرَة : إِنَّهُ الذَّلِيل . الرُّمَّانِيّ : الْمَهِين الْوَضِيع لِإِكْثَارِهِ مِنْ الْقَبِيح . وَهُوَ فَعِيل مِنْ الْمَهَانَة بِمَعْنَى الْقِلَّة . وَهِيَ هُنَا الْقِلَّة فِي الرَّأْي وَالتَّمْيِيز . أَوْ هُوَ فَعِيل بِمَعْنَى مُفْعَل ; وَالْمَعْنَى مُهَان .';
$t[11] = 'قَالَ اِبْن زَيْد : الْهَمَّاز الَّذِي يَهْمِز النَّاس بِيَدِهِ وَيَضْرِبهُمْ . وَاللَّمَّاز بِاللِّسَانِ . وَقَالَ الْحَسَن : هُوَ الَّذِي يَهْمِز نَاحِيَة فِي الْمَجْلِس ; كَقَوْلِهِ تَعَالَى : &quot; هُمَزَة &quot; . [ الْهُمَزَة : 1 ] . وَقِيلَ : الْهَمَّاز الَّذِي يَذْكُر النَّاس فِي وُجُوههمْ . وَاللَّمَّاز الَّذِي يَذْكُرهُمْ فِي مَغِيبهمْ ; قَالَهُ أَبُو الْعَالِيَة وَعَطَاء بْن أَبِي رَبَاح وَالْحَسَن أَيْضًا . وَقَالَ مُقَاتِل ضِدّ هَذَا الْكَلَام : إِنَّ الْهُمَزَة الَّذِي يَغْتَاب بِالْغَيْبَةِ . وَاللُّمَزَة الَّذِي يَغْتَاب فِي الْوَجْه . وَقَالَ مُرَّة : هُمَا سَوَاء . وَهُوَ الْقَتَّات الطَّعَّان لِلْمَرْءِ إِذَا غَابَ . وَنَحْوه عَنْ اِبْن عَبَّاس وَقَتَادَة . قَالَ الشَّاعِر : تُدْلِي بِوُدٍّ إِذَا لَاقَيْتنِي كَذِبًا وَإِنْ أَغِبْ فَأَنْتَ الْهَامِز اللُّمَزَة

أَيْ يَمْشِي بِالنَّمِيمَةِ بَيْنَ النَّاس لِيُفْسِد بَيْنهمْ . يُقَال : نَمّ يَنِمّ نَمًّا وَنَمِيمًا وَنَمِيمَة ; أَيْ يَمْشِي وَيَسْعَى بِالْفَسَادِ . وَفِي صَحِيح مُسْلِم عَنْ حُذَيْفَة أَنَّهُ بَلَغَهُ أَنَّ رَجُلًا يَنِمّ الْحَدِيث , فَقَالَ حُذَيْفَة : سَمِعْت رَسُول اللَّه صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَقُول : ( لَا يَدْخُل الْجَنَّة نَمَّام ) . وَقَالَ الشَّاعِر : وَمَوْلًى كَبَيْتِ النَّمْل لَا خَيْر عِنْده لِمَوْلَاهُ إِلَّا سَعْيه بِنَمِيمِ قَالَ الْفَرَّاء : هُمَا لُغَتَانِ . وَقِيلَ : النَّمِيم جَمْع نَمِيمَة .';
$t[12] = 'أَيْ لِلْمَالِ أَنْ يُنْفَق فِي وُجُوهه . وَقَالَ اِبْن عَبَّاس : يَمْنَع عَنْ الْإِسْلَام وَلَده وَعَشِيرَته . وَقَالَ الْحَسَن : يَقُول لَهُمْ مَنْ دَخَلَ مِنْكُمْ فِي دِين مُحَمَّد لَا أَنْفَعهُ بِشَيْءٍ أَبَدًا .

أَيْ عَلَى النَّاس فِي الظُّلْم , مُتَجَاوِز لِلْحَدِّ , صَاحِب بَاطِل .

أَيْ ذِي إِثْم , وَمَعْنَاهُ أَثُوم , فَهُوَ فَعِيل بِمَعْنَى فَعُول .';
$t[13] = 'الْعُتُلّ الْجَافِي الشَّدِيد فِي كُفْره . وَقَالَ الْكَلْبِيّ وَالْفَرَّاء : هُوَ الشَّدِيد الْخُصُومَة بِالْبَاطِلِ . وَقِيلَ : إِنَّهُ الَّذِي يَعْتَلّ النَّاس فَيَجُرّهُمْ إِلَى حَبْس أَوْ عَذَاب . مَأْخُوذ مِنْ الْعَتْل وَهُوَ الْجَرُّ ; وَمِنْهُ قَوْله تَعَالَى : &quot; خُذُوهُ فَاعْتِلُوهُ &quot; [ الدُّخَان : 47 ] . وَفِي الصِّحَاح : وَعَتَلْت الرَّجُل أَعْتِلهُ وَأَعْتُلُهُ إِذَا جَذَبْته جَذْبًا عَنِيفًا . وَرَجُل مِعْتَل ( بِالْكَسْرِ ) . وَقَالَ يَصِف فَرَسًا : نَفْرَعهُ فَرْعًا وَلَسْنَا نَعْتِلهُ قَالَ اِبْن السِّكِّيت : عَتَلَهُ وَعَتَنَهُ , بِاللَّامِ وَالنُّون جَمِيعًا . وَالْعُتُلّ الْغَلِيظ الْجَافِي . وَالْعُتُلّ أَيْضًا : الرُّمْح الْغَلِيظ . وَرَجُل عَتِل ( بِالْكَسْرِ ) بَيِّن الْعَتَل ; أَيْ سَرِيع إِلَى الشَّرّ . وَيُقَال : لَا أَنْعَتِل مَعَك ; أَيْ لَا أَبْرَح مَكَانِي . وَقَالَ عُبَيْد بْن عُمَيْر : الْعُتُلّ الْأَكُول الشَّرُوب الْقَوِيّ الشَّدِيد يُوضَع فِي الْمِيزَان فَلَا يَزِن شَعِيرَة ; يَدْفَع الْمَلَك مِنْ أُولَئِكَ فِي جَهَنَّم بِالدَّفْعَةِ الْوَاحِدَة سَبْعِينَ أَلْفًا . وَقَالَ عَلِيّ بْن أَبِي طَالِب وَالْحَسَن : الْعُتُلّ الْفَاحِش السَّيِّئ الْخُلُق . وَقَالَ مَعْمَر : هُوَ الْفَاحِش اللَّئِيم . قَالَ الشَّاعِر : بِعُتُلٍّ مِنْ الرِّجَال زَنِيم غَيْر ذِي نَجْدَة وَغَيْر كَرِيم وَفِي صَحِيح مُسْلِم عَنْ حَارِثَة بْن وَهْب سَمِعَ النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ : ( أَلَا أُخْبِركُمْ بِأَهْلِ الْجَنَّة - قَالُوا بَلَى قَالَ - كُلّ ضَعِيف مُتَضَعِّف لَوْ أَقْسَمَ عَلَى اللَّه لَأَبَرّه . أَلَا أُخْبِركُمْ بِأَهْلِ النَّار - قَالُوا بَلَى قَالَ - كُلّ عُتُلّ جَوَّاظ مُسْتَكْبِر ) . فِي رِوَايَة عَنْهُ ( كُلّ جَوَّاظ زَنِيم مُتَكَبِّر ) . الْجَوَّاظ : قِيلَ هُوَ الْجَمُوع الْمَنُوع . وَقِيلَ الْكَثِير اللَّحْم الْمُخْتَال فِي مِشْيَته . وَذَكَرَ الْمَاوَرْدِيّ عَنْ شَهْر بْن حَوْشَب عَنْ عَبْد الرَّحْمَن بْن غَنْم , وَرَوَاهُ اِبْن مَسْعُود أَنَّ النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ : ( لَا يَدْخُل الْجَنَّة جَوَّاظ وَلَا جَعْظَرِيّ وَلَا الْعُتُلّ الزَّنِيم ) . فَقَالَ رَجُل : مَا الْجَوَّاظ وَمَا الْجَعْظَرِيّ وَمَا الْعُتُلّ الزَّنِيم ؟ فَقَالَ رَسُول اللَّه صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ : ( الْجَوَّاظ الَّذِي جَمَعَ وَمَنَعَ . وَالْجَعْظَرِيّ الْغَلِيظ . وَالْعُتُلّ الزَّنِيم الشَّدِيد الْخَلْق الرَّحِيب الْجَوْف الْمُصَحَّح الْأَكُول الشَّرُوب الْوَاجِد لِلطَّعَامِ الظَّلُوم لِلنَّاسِ ) . وَذَكَرَهُ الثَّعْلَبِيّ عَنْ شَدَّاد بْن أَوْس : ( لَا يَدْخُل الْجَنَّة جَوَّاظ وَلَا جَعْظَرِيّ وَلَا عُتُلّ زَنِيم ) سَمِعْتهنَّ مِنْ النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قُلْت : وَمَا الْجَوَّاظ ؟ قَالَ : الْجَمَّاع الْمَنَّاع . قُلْت : وَمَا الْجَعْظَرِيّ ؟ قَالَ : الْفَظّ الْغَلِيظ . قُلْت : وَمَا الْعُتُلّ الزَّنِيم ؟ قَالَ : الرَّحِيب الْجَوْف الْوَثِير الْخَلْق الْأَكُول الشَّرُوب الْغَشُوم الظَّلُوم . قُلْت : فَهَذَا التَّفْسِير مِنْ النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فِي الْعُتُلّ قَدْ أَرْبَى عَلَى أَقْوَال الْمُفَسِّرِينَ . وَوَقَعَ فِي كِتَاب أَبِي دَاوُدَ فِي تَفْسِير الْجَوَّاظ أَنَّهُ الْفَظّ الْغَلِيظ . ذَكَرَهُ مِنْ حَدِيث حَارِثَة بْن وَهْب الْخُزَاعِيّ قَالَ : قَالَ رَسُول اللَّه صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ : ( لَا يَدْخُل الْجَنَّة الْجَوَّاظ وَلَا الْجَعْظَرِيّ ) قَالَ : وَالْجَوَّاظ الْفَظّ الْغَلِيظ . فَفِيهِ تَفْسِيرَانِ مَرْفُوعَانِ حَسْب مَا ذَكَرْنَاهُ أَوَّلًا . وَقَدْ قِيلَ : إِنَّهُ الْجَافِي الْقَلْب . وَعَنْ زَيْد بْن أَسْلَمَ فِي قَوْله تَعَالَى : &quot; عُتُلّ بَعْد ذَلِكَ زَنِيم &quot; قَالَ : قَالَ النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ : ( تَبْكِي السَّمَاء مِنْ رَجُل أَصَحّ اللَّه جِسْمه وَرَحَّبَ جَوْفه وَأَعْطَاهُ مِنْ الدُّنْيَا بَعْضًا فَكَانَ لِلنَّاسِ ظَلُومًا فَذَلِكَ الْعُتُلّ الزَّنِيم . وَتَبْكِي السَّمَاء مِنْ الشَّيْخ الزَّانِي مَا تَكَاد الْأَرْض تُقِلّهُ ) . وَالزَّنِيم الْمُلْصَق بِالْقَوْمِ الدَّعِيّ ; عَنْ اِبْن عَبَّاس وَغَيْره . قَالَ الشَّاعِر : زَنِيم تَدَاعَاهُ الرِّجَال زِيَادَة كَمَا زِيدَ فِي عَرْض الْأَدِيم الْأَكَارِع وَعَنْ اِبْن عَبَّاس أَيْضًا أَنَّهُ رَجُل مِنْ قُرَيْش كَانَتْ لَهُ زَنَمَة كَزَنَمَةِ الشَّاة . وَرَوَى عَنْهُ اِبْن جُبَيْر . أَنَّهُ الَّذِي يُعْرَف بِالشَّرِّ كَمَا تُعْرَف الشَّاة بِزَنَمَتِهَا . وَقَالَ عِكْرِمَة : هُوَ اللَّئِيم الَّذِي يُعْرَف بِلُؤْمِهِ كَمَا تُعْرَف الشَّاة بِزَنَمَتِهَا . وَقِيلَ : إِنَّهُ الَّذِي يَعْرِف بِالْأُبْنَةِ . وَهُوَ مَرْوِيّ عَنْ اِبْن عَبَّاس أَيْضًا . وَعَنْهُ أَنَّهُ الظَّلُوم . فَهَذِهِ سِتَّة أَقْوَال . وَقَالَ مُجَاهِد : زَنِيم كَانَتْ لَهُ سِتَّة أَصَابِع فِي يَده , فِي كُلّ إِبْهَام لَهُ إِصْبَع زَائِدَة . وَعَنْهُ أَيْضًا وَسَعِيد بْن الْمُسَيِّب وَعِكْرِمَة : هُوَ وَلَد الزِّنَا الْمُلْحَق فِي النَّسَب بِالْقَوْمِ . وَكَانَ الْوَلِيد دَعِيًّا فِي قُرَيْش لَيْسَ مِنْ سِنْخهمْ ; اِدَّعَاهُ أَبُوهُ بَعْد ثَمَانِي عَشْرَة سَنَة مِنْ مَوْلِده . قَالَ الشَّاعِر : زَنِيم لَيْسَ يُعْرَف مَنْ أَبُوهُ بَغِيّ الْأُمّ ذُو حَسَب لَئِيم وَقَالَ حَسَّان : وَأَنْتَ زَنِيم نِيطَ فِي آل هَاشِم كَمَا نِيطَ خَلْف الرَّاكِب الْقَدَح الْفَرْد قُلْت : وَهَذَا هُوَ الْقَوْل الْأَوَّل بِعَيْنِهِ . وَعَنْ عَلِيّ رَضِيَ اللَّه تَعَالَى عَنْهُ أَنَّهُ الَّذِي لَا أَصْل لَهُ ; وَالْمَعْنَى وَاحِد . وَرُوِيَ أَنَّ النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ : ( لَا يَدْخُل الْجَنَّة وَلَد زِنًا وَلَا وَلَده وَلَا وَلَد وَلَده ) . وَقَالَ عَبْد اللَّه بْن عُمَر : إِنَّ النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ : ( إِنَّ أَوْلَاد الزِّنَا يُحْشَرُونَ يَوْم الْقِيَامَة فِي صُورَة الْقِرَدَة وَالْخَنَازِير ) . وَقَالَتْ مَيْمُونَة : سَمِعْت النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَقُول : ( لَا تَزَال أُمَّتِي بِخَيْرٍ مَا لَمْ يَفْشُ فِيهِمْ وَلَد الزِّنَا فَإِذَا فَشَا فِيهِمْ وَلَد الزِّنَا أَوْشَكَ أَنْ يَعُمّهُمْ اللَّه بِعِقَابٍ ) . وَقَالَ عِكْرِمَة : إِذَا كَثُرَ وَلَد الزِّنَا قَحَطَ الْمَطَر . قُلْت : أَمَّا الْحَدِيث الْأَوَّل وَالثَّانِي فَمَا أَظُنّ لَهُمَا سَنَدًا يَصِحّ , وَأَمَّا حَدِيث مَيْمُونَة وَمَا قَالَهُ عِكْرِمَة فَفِي صَحِيح مُسْلِم عَنْ زَيْنَب بِنْت جَحْش زَوْج النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَتْ : خَرَجَ النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَوْمًا فَزِعًا مُحْمَرًّا وَجْهه يَقُول : ( لَا إِلَه إِلَّا اللَّه . وَيْل لِلْعَرَبِ مِنْ شَرّ قَدْ اِقْتَرَبَ . فُتِحَ الْيَوْم مِنْ رَدْم يَأْجُوج وَمَأْجُوج مِثْل هَذِهِ ) وَحَلَّقَ بِإِصْبَعَيْهِ الْإِبْهَام وَاَلَّتِي تَلِيهَا . قَالَتْ فَقُلْت : يَا رَسُول اللَّه , أَنَهْلَكُ وَفِينَا الصَّالِحُونَ ؟ قَالَ : ( نَعَمْ إِذَا كَثُرَ الْخَبَث ) خَرَّجَهُ الْبُخَارِيّ . وَكَثْرَة الْخَبَث ظُهُور الزِّنَا وَأَوْلَاد الزِّنَا ; كَذَا فَسَّرَهُ الْعُلَمَاء . وَقَوْل عِكْرِمَة &quot; قَحْط الْمَطَر &quot; تَبْيِين لِمَا يَكُون بِهِ الْهَلَاك . وَهَذَا يَحْتَاج إِلَى تَوْقِيف , وَهُوَ أَعْلَم مِنْ أَيْنَ قَالَهُ . وَمُعْظَم الْمُفَسِّرِينَ عَلَى أَنَّ هَذَا نَزَلَ فِي الْوَلِيد بْن الْمُغِيرَة , وَكَانَ يُطْعِم أَهْل مِنًى حَيْسًا ثَلَاثَة أَيَّام , وَيُنَادِي أَلَا لَا يُوقِدَنَّ أَحَد تَحْت بُرْمَة , أَلَا لَا يُدَخِّنَنَّ أَحَد بِكُرَاعٍ , أَلَا وَمَنْ أَرَادَ الْحَيْس فَلْيَأْتِ الْوَلِيد بْن الْمُغِيرَة . وَكَانَ يُنْفِق فِي الْحَجَّة الْوَاحِدَة عِشْرِينَ أَلْفًا وَأَكْثَرَ . وَلَا يُعْطِي الْمِسْكِين دِرْهَمًا وَاحِدًا فَقِيلَ : &quot; مَنَّاع لِلْخَيْرِ &quot; . وَفِيهِ نَزَلَ : &quot; وَيْل لِلْمُشْرِكِينَ . الَّذِينَ لَا يُؤْتُونَ الزَّكَاة &quot; [فُصِّلَتْ : 6 - 7 ] . وَقَالَ مُحَمَّد بْن إِسْحَاق : نَزَلَتْ فِي الْأَخْنَس بْن شَرِيق , لِأَنَّهُ حَلِيف مُلْحَق فِي بَنِي زُهْرَة , فَلِذَلِكَ سُمِّيَ زَنِيمًا . وَقَالَ اِبْن عَبَّاس : فِي هَذِهِ الْآيَة نُعِتَ , فَلَمْ يُعْرَف حَتَّى قُتِلَ فَعُرِفَ , وَكَانَ لَهُ زَنَمَة فِي عُنُقه مُعَلَّقَة يُعْرَف بِهَا . وَقَالَ مُرَّة الْهَمْدَانِيّ : إِنَّمَا اِدَّعَاهُ أَبُوهُ بَعْد ثَمَانِي عَشْرَة سَنَة .';
$t[14] = 'قَرَأَ أَبُو جَعْفَر وَابْن عَامِر وَأَبُو حَيْوَةَ وَالْمُغِيرَة وَالْأَعْرَج &quot; آن كَانَ &quot; بِهَمْزَةٍ وَاحِدَة مَمْدُودَة عَلَى الِاسْتِفْهَام . وَقَرَأَ الْمُفَضَّل وَأَبُو بَكْر وَحَمْزَة &quot; أَأَنْ كَانَ &quot; بِهَمْزَتَيْنِ مُحَقَّقَتَيْنِ . وَقَرَأَ الْبَاقُونَ بِهَمْزَةٍ وَاحِدَة عَلَى الْخَبَر ; فَمَنْ قَرَأَ بِهَمْزَةٍ مُطَوَّلَة أَوْ بِهَمْزَتَيْنِ مُحَقَّقَتَيْنِ فَهُوَ اِسْتِفْهَام وَالْمُرَاد بِهِ التَّوْبِيخ , وَيَحْسُن لَهُ أَنْ يَقِف عَلَى &quot; زَنِيم &quot; , وَيَبْتَدِئ &quot; أَنْ كَانَ &quot; عَلَى مَعْنَى أَلِأَنْ كَانَ ذَا مَال وَبَنِينَ تُطِيعهُ . وَيَجُوز أَنْ يَكُون التَّقْدِير : أَلِأَنْ كَانَ ذَا مَال وَبَنِينَ يَقُول إِذَا تُتْلَى عَلَيْهِ آيَاتنَا : أَسَاطِير الْأَوَّلِينَ وَيَجُوز أَنْ يَكُون التَّقْدِير : أَلِأَنْ كَانَ ذَا مَال وَبَنِينَ يَكْفُر وَيَسْتَكْبِر . وَدَلَّ عَلَيْهِ مَا تَقَدَّمَ مِنْ الْكَلَام فَصَارَ كَالْمَذْكُورِ بَعْد الِاسْتِفْهَام . وَمَنْ قَرَأَ &quot; أَنْ كَانَ &quot; بِغَيْرِ اِسْتِفْهَام فَهُوَ مَفْعُول مِنْ أَجْله وَالْعَامِل فِيهِ فِعْل مُضْمَر , وَالتَّقْدِير : يَكْفُر لِأَنْ كَانَ ذَا مَال وَبَنِينَ .';
$t[15] = 'وَدَلَّ عَلَى هَذَا الْفِعْل : &quot; إِذَا تُتْلَى عَلَيْهِ آيَاتنَا قَالَ أَسَاطِير الْأَوَّلِينَ &quot; وَلَا يَعْمَل فِي &quot; أَنْ &quot; : &quot; تُتْلَى &quot; وَلَا &quot; قَالَ &quot; لِأَنَّ مَا بَعْد &quot; إِذَا &quot; لَا يَعْمَل فِيمَا قَبْلهَا ; لِأَنَّ &quot; إِذَا &quot; تُضَاف إِلَى الْجُمَل الَّتِي بَعْدهَا , وَلَا يَعْمَل الْمُضَاف إِلَيْهِ فِيمَا قَبْل الْمُضَاف . و &quot; قَالَ &quot; جَوَاب الْجَزَاء وَلَا يَعْمَل فِيمَا قَبْل الْجَزَاء ; إِذْ حُكْم الْعَامِل أَنْ يَكُون قَبْل الْمَعْمُول فِيهِ , وَحُكْم الْجَوَاب أَنْ يَكُون بَعْد الشَّرْط فَيَصِير مُقَدَّمًا مُؤَخَّرًا فِي حَال . وَيَجُوز أَنْ يَكُون الْمَعْنَى لَا تُطِعْهُ لِأَنْ كَانَ ذَا يَسَار وَعَدَد . قَالَ اِبْن الْأَنْبَارِيّ : وَمَنْ قَرَأَ بِلَا اِسْتِفْهَام لَمْ يَحْسُن أَنْ يَقِف عَلَى &quot; زَنِيم &quot; لِأَنَّ الْمَعْنَى لِأَنْ كَانَ وَبِأَنْ كَانَ , &quot; فَأَنْ &quot; مُتَعَلِّقَة بِمَا قَبْلهَا . قَالَ غَيْره : يَجُوز أَنْ يَتَعَلَّق بِقَوْلِهِ : &quot; مَشَّاء بِنَمِيمٍ &quot; وَالتَّقْدِير يَمْشِي بِنَمِيمٍ لِأَنْ كَانَ ذَا مَال وَبَنِينَ . وَأَجَازَ أَبُو عَلِيّ أَنْ يَتَعَلَّق &quot; بِعُتُلٍّ &quot; .

وَأَسَاطِير الْأَوَّلِينَ : أَبَاطِيلهمْ وَتُرَّهَاتهمْ وَخُرَافَاتهمْ . وَقَدْ تَقَدَّمَ .';
$t[16] = 'فِيهِ مَسْأَلَتَانِ : الْأُولَى : قَوْله تَعَالَى : &quot; سَنَسِمُهُ &quot; قَالَ اِبْن عَبَّاس : مَعْنَى &quot; سَنَسِمُهُ &quot; سَنَخْطِمُهُ بِالسَّيْفِ . قَالَ : وَقَدْ خُطِمَ الَّذِي نَزَلَتْ فِيهِ يَوْم بَدْر بِالسَّيْفِ ; فَلَمْ يَزَلْ مَخْطُومًا إِلَى أَنْ مَاتَ . وَقَالَ قَتَادَة : سَنَسِمُهُ يَوْم الْقِيَامَة عَلَى أَنْفه سِمَة يُعْرَف بِهَا ; يُقَال : وَسَمْته وَسْمًا وَسِمَة إِذَا أَثَّرْت فِيهِ بِسِمَةٍ وَكَيّ . وَقَدْ قَالَ تَعَالَى : &quot; يَوْم تَبْيَضّ وُجُوه وَتَسْوَدّ وُجُوه &quot; [ آل عِمْرَان : 106 ] فَهَذِهِ عَلَامَة ظَاهِرَة . وَقَالَ تَعَالَى : &quot; وَنَحْشُر الْمُجْرِمِينَ يَوْمئِذٍ زُرْقًا &quot; [ طَه : 102 ] وَهَذِهِ عَلَامَة أُخْرَى ظَاهِرَة . فَأَفَادَتْ هَذِهِ الْآيَة عَلَامَة ثَالِثَة وَهِيَ الْوَسْم عَلَى الْأَنْف بِالنَّارِ ; وَهَذَا كَقَوْلِهِ تَعَالَى : &quot; يُعْرَف الْمُجْرِمُونَ بِسِيمَاهُمْ &quot; [ الرَّحْمَن : 41 ] قَالَهُ الْكَلْبِيّ وَغَيْره . وَقَالَ أَبُو الْعَالِيَة وَمُجَاهِد : &quot; سَنَسِمُهُ عَلَى الْخُرْطُوم &quot; أَيْ عَلَى أَنْفه , وَنُسَوِّد وَجْهه فِي الْآخِرَة فَيُعْرَف بِسَوَادِ وَجْهه . وَالْخُرْطُوم : الْأَنْف مِنْ الْإِنْسَان . وَمِنْ السِّبَاع : مَوْضِع الشَّفَة . وَخَرَاطِيم الْقَوْم : سَادَاتهمْ . قَالَ الْفَرَّاء : وَإِنْ كَانَ الْخُرْطُوم قَدْ خُصَّ بِالسِّمَةِ فَإِنَّهُ فِي مَعْنَى الْوَجْه ; لِأَنَّ بَعْض الشَّيْء يُعَبَّر بِهِ عَنْ الْكُلّ . وَقَالَ الطَّبَرِيّ : نُبَيِّن أَمْره تِبْيَانًا وَاضِحًا حَتَّى يَعْرِفُوهُ فَلَا يَخْفَى عَلَيْهِمْ كَمَا لَا تَخْفَى السِّمَة عَلَى الْخَرَاطِيم . وَقِيلَ : الْمَعْنَى سَنُلْحِقُ بِهِ عَارًا وَسُبَّة حَتَّى يَكُون كَمَنْ وُسِمَ عَلَى أَنْفه . قَالَ الْقُتَبِيّ : تَقُول الْعَرَب لِلرَّجُلِ يُسَبّ سُبَّة سُوء قَبِيحَة بَاقِيَة : قَدْ وُسِمَ مِيسَم سُوء ; أَيْ أُلْصِقَ بِهِ عَار لَا يُفَارِقهُ ; كَمَا أَنَّ السِّمَة لَا يُمْحَى أَثَرهَا . قَالَ جَرِير : لَمَّا وَضَعْت عَلَى الْفَرَزْدَق مِيسَمِي وَعَلَى الْبَعِيثِ جَدَعْت أَنْف الْأَخْطَل أَرَادَ بِهِ الْهِجَاء . قَالَ : وَهَذَا كُلّه نَزَلَ فِي الْوَلِيد بْن الْمُغِيرَة . وَلَا نَعْلَم أَنَّ اللَّه تَعَالَى بَلَغَ مِنْ ذِكْر عُيُوب أَحَد مَا بَلَغَهُ مِنْهُ ; فَأَلْحَقَهُ بِهِ عَارًا لَا يُفَارِقهُ فِي الدُّنْيَا وَالْآخِرَة ; كَالْوَسْمِ عَلَى الْخُرْطُوم . وَقِيلَ : هُوَ مَا اِبْتَلَاهُ اللَّه بِهِ فِي الدُّنْيَا فِي نَفْسه وَمَاله وَأَهْله مِنْ سُوء وَذُلّ وَصَغَار ; قَالَهُ اِبْن بَحْر . وَاسْتَشْهَدَ بِقَوْلِ الْأَعْشَى : فَدَعْهَا وَمَا يُغْنِيك وَاعْمِدْ لِغَيْرِهَا بِشَعْرِك وَاعْلُبْ أَنْف مَنْ أَنْتَ وَاسِم وَقَالَ النَّضْر بْن شُمَيْلٍ : الْمَعْنَى سَنَحُدُّهُ عَلَى شُرْب الْخَمْر , وَالْخُرْطُوم : الْخَمْر , وَجَمْعه خَرَاطِيم , قَالَ الشَّاعِر : تَظَلّ يَوْمك فِي لَهْو وَفِي طَرَب وَأَنْتَ بِاللَّيْلِ شَرَّاب الْخَرَاطِيم قَالَ الرَّاجِز : صَهْبَاء خُرْطُومًا عَقَارًا قَرْقَفَا وَقَالَ آخَر : أَبَا حَاضِر مَنْ يَزْنِ يُعْرَف زِنَاؤُهُ وَمَنْ يَشْرَب الْخُرْطُوم يُصْبِح مُسْكَرًا الثَّانِيَة : قَالَ اِبْن الْعَرَبِيّ : &quot; كَانَ الْوَسْم فِي الْوَجْه لِذِي الْمَعْصِيَة قَدِيمًا عِنْد النَّاس , حَتَّى أَنَّهُ رُوِيَ - كَمَا تَقَدَّمَ - أَنَّ الْيَهُود لَمَّا أَهْمَلُوا رَجْم الزَّانِي اعْتَاضُوا مِنْهُ بِالضَّرْبِ وَتَحْمِيم الْوَجْه ; وَهَذَا وَضْع بَاطِل . وَمِنْ الْوَسْم الصَّحِيح فِي الْوَجْه : مَا رَأَى الْعُلَمَاء مِنْ تَسْوِيد وَجْه شَاهِد الزُّور , عَلَامَة عَلَى قُبْح الْمَعْصِيَة وَتَشْدِيدًا لِمَنْ يَتَعَاطَاهَا لِغَيْرِهِ مِمَّنْ يُرْجَى تَجَنُّبه بِمَا يُرْجَى مِنْ عُقُوبَة شَاهِد الزُّور وَشُهْرَته ; فَقَدْ كَانَ عَزِيزًا بِقَوْلِ الْحَقّ وَقَدْ صَارَ مَهِينًا بِالْمَعْصِيَةِ . وَأَعْظَم الْإِهَانَة إِهَانَة الْوَجْه . وَكَذَلِكَ كَانَتْ الِاسْتِهَانَة بِهِ فِي طَاعَة اللَّه سَبَبًا لِخِيرَةِ الْأَبَد وَالتَّحْرِيم لَهُ عَلَى النَّار ; فَإِنَّ اللَّه تَعَالَى قَدْ حَرَّمَ عَلَى النَّار أَنْ تَأْكُل مِنْ اِبْن آدَم أَثَر السُّجُود ; حَسْب مَا ثَبَتَ فِي الصَّحِيح .';
$t[17] = '&quot; إِنَّا بَلَوْنَاهُمْ &quot; يُرِيد أَهْل مَكَّة . وَالِابْتِلَاء الِاخْتِبَار . وَالْمَعْنَى أَعْطَيْنَاهُمْ أَمْوَالًا لِيَشْكُرُوا لَا لِيَبْطَرُوا ; فَلَمَّا بَطِرُوا وَعَادَوْا مُحَمَّدًا صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ اِبْتَلَيْنَاهُمْ بِالْجُوعِ وَالْقَحْط كَمَا بَلَوْنَا أَهْل الْجَنَّة الْمَعْرُوف خَبَرهَا عِنْدهمْ . وَذَلِكَ أَنَّهَا كَانَتْ بِأَرْضِ الْيَمَن بِالْقُرْبِ مِنْهُمْ عَلَى فَرَاسِخ مِنْ صَنْعَاء - وَيُقَال بِفَرْسَخَيْنِ - وَكَانَتْ لِرَجُلٍ يُؤَدِّي حَقّ اللَّه تَعَالَى مِنْهَا ; فَلَمَّا مَاتَ صَارَتْ إِلَى وَلَده , فَمَنَعُوا النَّاس خَيْرهَا وَبَخِلُوا بِحَقِّ اللَّه فِيهَا ; فَأَهْلَكَهَا اللَّه مِنْ حَيْثُ لَمْ يُمْكِنهُمْ دَفْع مَا حَلَّ بِهَا . قَالَ الْكَلْبِيّ : كَانَ بَيْنهمْ وَبَيْنَ صَنْعَاء فَرْسَخَانِ ; اِبْتَلَاهُمْ اللَّه بِأَنْ أَحْرَقَ جَنَّتهمْ . وَقِيلَ : هِيَ جَنَّة بِضَوْرَانَ , وَضَوْرَانُ عَلَى فَرْسَخ مِنْ صَنْعَاء , وَكَانَ أَصْحَاب هَذِهِ الْجَنَّة بَعْد رَفْع عِيسَى عَلَيْهِ السَّلَام بِيَسِيرٍ - وَكَانُوا بُخَلَاء - فَكَانُوا يَجُدُّونَ التَّمْر لَيْلًا مِنْ أَجْل الْمَسَاكِين , وَكَانُوا أَرَادُوا حَصَاد زَرْعهَا وَقَالُوا : لَا يَدْخُلهَا الْيَوْم عَلَيْكُمْ مِسْكِين , فَغَدَوْا عَلَيْهَا فَإِذَا هِيَ قَدْ اُقْتُلِعَتْ مِنْ أَصْلهَا فَأَصْبَحَتْ كَالصَّرِيمِ ; أَيْ كَاللَّيْلِ . وَيُقَال أَيْضًا لِلنَّهَارِ صَرِيم . فَإِنْ كَانَ أَرَادَ اللَّيْل فَلَا سَوَاد مَوْضِعهَا . وَكَأَنَّهُمْ وَجَدُوا مَوْضِعهَا حَمْأَة . وَإِنْ كَانَ أَرَادَ بِالصَّرِيمِ النَّهَار فَلِذَهَابِ الشَّجَر وَالزَّرْع وَنَقَاء الْأَرْض مِنْهُ . وَكَانَ الطَّائِف الَّذِي طَافَ عَلَيْهَا جِبْرِيل عَلَيْهِ السَّلَام فَاقْتَلَعَهَا . فَيُقَال : إِنَّهُ طَافَ بِهَا حَوْل الْبَيْت ثُمَّ وَضَعَهَا حَيْثُ مَدِينَة الطَّائِف الْيَوْم ; وَلِذَلِكَ سُمِّيَتْ الطَّائِف . وَلَيْسَ فِي أَرْض الْحِجَاز بَلْدَة فِيهَا الشَّجَر وَالْأَعْنَاب وَالْمَاء غَيْرهَا . وَقَالَ الْبَكْرِيّ فِي الْمُعْجَم : سُمِّيَتْ الطَّائِف لِأَنَّ رَجُلًا مِنْ الصَّدِف يُقَال لَهُ الدَّمُون , بَنَى حَائِطًا وَقَالَ : قَدْ بَنَيْت لَكُمْ طَائِفًا حَوْل بَلَدكُمْ ; فَسُمِّيَتْ الطَّائِف . وَاَللَّه أَعْلَم .

قَالَ بَعْض الْعُلَمَاء : عَلَى مَنْ حَصَدَ زَرْعًا أَوْ جَدّ ثَمَرَة أَنْ يُوَاسِيَ مِنْهَا مَنْ حَضَرَهُ ; وَذَلِكَ مَعْنَى قَوْله : &quot; وَآتُوا حَقَّهُ يَوْمَ حَصَاده &quot; [ الْأَنْعَام : 141 ] وَأَنَّهُ غَيْر الزَّكَاة عَلَى مَا تَقَدَّمَ فِي &quot; الْأَنْعَام &quot; بَيَانه . وَقَالَ بَعْضهمْ : وَعَلَيْهِ تَرَكَ مَا أَخْطَأَهُ الْحَاصِدُونَ . وَكَانَ بَعْض الْعِبَاد يَتَحَرَّوْنَ أَقْوَاتَهُمْ مِنْ هَذَا . وَرُوِيَ أَنَّهُ نُهِيَ عَنْ الْحَصَاد بِاللَّيْلِ . فَقِيلَ : إِنَّهُ لِمَا يَنْقَطِع عَنْ الْمَسَاكِين فِي ذَلِكَ مِنْ الرِّفْق . وَتَأَوَّلَ مَنْ قَالَ هَذَا الْآيَة الَّتِي فِي سُورَة &quot; ن وَالْقَلَم &quot; . قِيلَ : إِنَّمَا نَهِيَ عَنْ ذَلِكَ خَشْيَة الْحَيَّات وَهَوَامّ الْأَرْض . قُلْت : الْأَوَّل أَصَحّ ; وَالثَّانِي حَسَن . وَإِنَّمَا قُلْنَا الْأَوَّل أَصَحّ لِأَنَّ الْعُقُوبَةَ كَانَتْ بِسَبَبِ مَا أَرَادُوهُ مِنْ مَنْع الْمَسَاكِين كَمَا ذَكَرَ اللَّه تَعَالَى . رَوَى أَسْبَاط عَنْ السُّدِّيّ قَالَ : كَانَ قَوْم بِالْيَمَنِ وَكَانَ أَبُوهُمْ رَجُلًا صَالِحًا , وَكَانَ إِذَا بَلَغَ ثِمَارَهُ أَتَاهُ الْمَسَاكِين فَمَا يَمْنَعهُمْ مِنْ دُخُولهَا وَأَنْ يَأْكُلُوا مِنْهَا وَيَتَزَوَّدُوا ; فَلَمَّا مَاتَ قَالَ بَنُوهُ بَعْضُهُمْ لِبَعْضٍ : عَلَامَ نُعْطِي أَمْوَالَنَا هَؤُلَاءِ الْمَسَاكِين ! تَعَالَوْا فَلْنُدْلِجْ فَنَصْرِمنَّهَا قَبْل أَنْ يَعْلَمَ الْمَسَاكِين ; وَلَمْ يَسْتَثْنُوا ; فَانْطَلَقُوا وَبَعْضهمْ يَقُول لِبَعْضٍ خَفْتًا : لَا يَدْخُلَنَّهَا الْيَوْمَ عَلَيْكُمْ مِسْكِينٌ ; فَذَلِكَ قَوْله تَعَالَى : &quot; إِذْ أَقْسَمُوا &quot; يَعْنِي حَلَفُوا فِيمَا بَيْنَهُمْ &quot; لِيَصْرِمُنَّهَا مُصْبِحِينَ &quot; يَعْنِي لَنَجُذَّنَّهَا وَقْت الصُّبْح قَبْل أَنْ تَخْرُجَ الْمَسَاكِين ; وَلَا يَسْتَثْنُونَ ; يَعْنِي لَمْ يَقُولُوا إِنْ شَاءَ اللَّه . وَقَالَ اِبْن عَبَّاس : كَانَتْ تِلْكَ الْجَنَّة دُون صَنْعَاء بِفَرْسَخَيْنِ , غَرَسَهَا رَجُل مِنْ أَهْل الصَّلَاح وَكَانَ لَهُ ثَلَاثَة بَنِينَ , وَكَانَ لِلْمَسَاكِينِ كُلّ مَا تَعَدَّاهُ الْمِنْجَل فَلَمْ يَجُذّهُ مِنْ الْكَرْم , فَإِذَا طُرِحَ عَلَى الْبِسَاط فَكُلّ شَيْء سَقَطَ عَنْ الْبِسَاط فَهُوَ أَيْضًا لِلْمَسَاكِينِ , فَإِذَا حَصَدُوا زَرْعَهُمْ فَكُلّ شَيْء تَعَدَّاهُ الْمِنْجَل فَهُوَ لِلْمَسَاكِينِ , فَإِذَا دَرَسُوا كَانَ لَهُمْ كُلّ شَيْء اِنْتَثَرَ ; فَكَانَ أَبُوهُمْ يَتَصَدَّق مِنْهَا عَلَى الْمَسَاكِين , وَكَانَ يَعِيش فِي ذَلِكَ فِي حَيَاة أَبِيهِمْ الْيَتَامَى وَالْأَرَامِل وَالْمَسَاكِين , فَلَمَّا مَاتَ أَبُوهُمْ فَعَلُوا مَا ذَكَرَ اللَّه عَنْهُمْ . فَقَالُوا : قَلَّ الْمَال وَكَثُرَ الْعِيَال ; فَتَحَالَفُوا بَيْنَهُمْ لَيَغْدُوُنَّ غَدْوَة قَبْل خُرُوج النَّاس ثُمَّ لَيَصْرِمُنَّهَا وَلَا تَعْرِف الْمَسَاكِين . وَهُوَ قَوْله : &quot; إِذْ أَقْسَمُوا &quot; أَيْ حَلَفُوا &quot; لِيَصْرِمُنَّهَا &quot; لَيَقْطَعُنَّ ثَمَر نَخِيلهمْ إِذَا أَصْبَحُوا بِسُدْفَةٍ مِنْ اللَّيْل لِئَلَّا يَنْتَبِه الْمَسَاكِين لَهُمْ . وَالصَّرْم الْقَطْع . يُقَال : صَرَمَ الْعِذْق عَنْ النَّخْلَة . وَأَصْرَمَ النَّخْلَ أَيْ حَانَ وَقْت صِرَامه . مِثْل أَرْكَبَ الْمُهْر وَأَحْصَدَ الزَّرْع , أَيْ حَانَ رُكُوبه وَحَصَاده .';
$t[18] = 'أَيْ وَلَمْ يَقُولُوا إِنْ شَاءَ اللَّه . وَقَالَ مُجَاهِد : كَانَ حَرْثهمْ عِنَبًا وَلَمْ يَقُولُوا إِنْ شَاءَ اللَّه . وَقَالَ أَبُو صَالِح : كَانَ اِسْتِثْنَاؤُهُمْ قَوْلهمْ سُبْحَانَ اللَّه رَبّنَا . وَقِيلَ : مَعْنَى &quot; وَلَا يَسْتَثْنُونَ &quot; أَيْ لَا يَسْتَثْنُونَ حَقّ الْمَسَاكِين ; قَالَهُ عِكْرِمَة .';
$t[19] = 'فَجَاءُوهَا لَيْلًا فَرَأَوْا الْجَنَّةَ مُسَوَّدَةً قَدْ طَافَ عَلَيْهَا طَائِف مِنْ رَبّك وَهُمْ نَائِمُونَ . قِيلَ : الطَّائِف جِبْرِيل عَلَيْهِ السَّلَام ; عَلَى مَا تَقَدَّمَ ذِكْره . وَقَالَ اِبْن عَبَّاس : أَمْر مِنْ رَبّك . وَقَالَ قَتَادَة : عَذَاب مِنْ رَبّك . اِبْن جُرَيْج : عُنُق مِنْ نَار خَرَجَ مِنْ وَادِي جَهَنَّم . وَالطَّائِف لَا يَكُون إِلَّا بِاللَّيْلِ ; قَالَهُ الْفَرَّاء .

قُلْت : فِي هَذِهِ الْآيَة دَلِيل عَلَى أَنَّ الْعَزْمَ مِمَّا يُؤَاخَذ بِهِ الْإِنْسَان ; لِأَنَّهُمْ عَزَمُوا عَلَى أَنْ يَفْعَلُوا فَعُوقِبُوا قَبْلَ فِعْلهمْ . وَنَظِير هَذِهِ الْآيَة قَوْله تَعَالَى : &quot; وَمَنْ يُرِدْ فِيهِ بِإِلْحَادٍ بِظُلْمٍ نُذِقْهُ مِنْ عَذَاب أَلِيم &quot; [ الْحَجّ : 25 ] . وَفِي الصَّحِيح عَنْ النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ : ( إِذَا اِلْتَقَى الْمُسْلِمَانِ بِسَيْفَيْهِمَا فَالْقَاتِل وَالْمَقْتُول فِي النَّار ) قِيلَ : يَا رَسُولَ اللَّه , هَذَا الْقَاتِل فَمَا بَالُ الْمَقْتُول ؟ قَالَ : ( إِنَّهُ كَانَ حَرِيصًا عَلَى قَتْل صَاحِبه ) . وَقَدْ مَضَى مُبَيَّنًا فِي سُورَة &quot; آل عِمْرَان &quot; عِنْدَ قَوْله تَعَالَى : &quot; وَلَمْ يُصِرُّوا عَلَى مَا فَعَلُوا &quot; [ آل عِمْرَان : 135 ] .';
$t[20] = 'أَيْ كَاللَّيْلِ الْمُظْلِم عَنْ اِبْن عَبَّاس وَالْفَرَّاء وَغَيْرهمَا . قَالَ الشَّاعِر : تَطَاوَلَ لَيْلُك الْجَوْن الْبَهِيم فَمَا يَنْجَاب عَنْ صُبْح صَرِيم أَيْ اِحْتَرَقَتْ فَصَارَتْ كَاللَّيْلِ الْأَسْوَد . وَعَنْ اِبْن عَبَّاس أَيْضًا : كَالرَّمَادِ الْأَسْوَد . قَالَ : الصَّرِيم الرَّمَاد الْأَسْوَد بِلُغَةِ خُزَيْمَةَ . الثَّوْرِيّ : كَالزَّرْعِ الْمَحْصُود . فَالصَّرِيم بِمَعْنَى الْمَصْرُوم أَيْ الْمَقْطُوع مَا فِيهِ . وَقَالَ الْحَسَن : صُرِمَ عَنْهَا الْخَيْرَ أَيْ قُطِعَ ; فَالصَّرِيم مَفْعُول أَيْضًا . وَقَالَ الْمُؤَرِّج : أَيْ كَالرَّمْلَةِ اِنْصَرَمَتْ مِنْ مُعْظَم الرَّمْل . يُقَال : صَرِيمَة وَصَرَائِم ; فَالرَّمْلَة لَا تُنْبِت شَيْئًا يُنْتَفَع بِهِ . وَقَالَ الْأَخْفَش : أَيْ كَالصُّبْحِ اِنْصَرَمَ مِنْ اللَّيْل . وَقَالَ الْمُبَرِّد : أَيْ كَالنَّهَارِ ; فَلَا شَيْءَ فِيهَا . قَالَ شَمِر : الصَّرِيم اللَّيْل وَالصَّرِيم النَّهَار ; أَيْ يَنْصَرِم هَذَا عَنْ ذَاكَ وَذَاكَ عَنْ هَذَا . وَقِيلَ : سُمِّيَ اللَّيْل صَرِيمًا لِأَنَّهُ يَقْطَع بِظُلْمَتِهِ عَنْ التَّصَرُّف ; وَلِهَذَا يَكُون فَعِيل بِمَعْنَى فَاعِل . قَالَ الْقُشَيْرِيّ : وَفِي هَذَا نَظَر ; لِأَنَّ النَّهَارَ يُسَمَّى صَرِيمًا وَلَا يَقْطَع عَنْ تَصَرُّف .';
$t[21] = '&quot; فَتَنَادَوْا مُصْبِحِينَ &quot; يُنَادِي بَعْضهمْ بَعْضًا لَيَقْطَعُنَّ ثَمَرَ نَخِيلهمْ إِذَا أَصْبَحُوا بِسَدْفَةٍ مِنْ اللَّيْل لِئَلَّا يَنْتَبِه الْمَسَاكِين';
$t[22] = 'عَازِمِينَ عَلَى الصِّرَام وَالْجِدَاد . قَالَ قَتَادَة : حَاصِدِينَ زَرْعَكُمْ . وَقَالَ الْكَلْبِيّ : مَا كَانَ فِي جَنَّتهمْ مِنْ زَرْع وَلَا نَخِيل . فَتَحَالَفُوا بَيْنهمْ لَيَغْدُوُنَّ غَدْوَة قَبْل خُرُوج النَّاس ثُمَّ لَيَصْرِمُنَّهَا وَلَا تَعْرِف الْمَسَاكِين';
$t[23] = 'أَيْ يَتَسَارُّونَ ; أَيْ يُخْفُونَ كَلَامَهُمْ وَيُسِرُّونَهُ لِئَلَّا يَعْلَمَ بِهِمْ أَحَد ; قَالَهُ عَطَاء وَقَتَادَة . وَهُوَ مِنْ خَفَتَ يَخْفِت إِذَا سَكَنَ وَلَمْ يُبَيِّن . كَمَا قَالَ دُرَيْد بْن الصِّمَّة : وَإِنِّي لَمْ أَهْلَك سُلَالًا وَلَمْ أَمُتْ خُفَاتًا وَكُلًّا ظَنَّهُ بِي عُوَّدِي وَقِيلَ : يُخْفُونَ أَنْفُسَهُمْ مِنْ النَّاس حَتَّى لَا يَرَوْهُمْ .';
$t[24] = 'وَكَانَ أَبُوهُمْ يُخْبِر الْفُقَرَاءَ وَالْمَسَاكِين فَيَحْضُرُوا وَقْتَ الْحَصَاد وَالصِّرَام .';
$t[25] = 'أَيْ عَلَى قَصْد وَقُدْرَة فِي أَنْفُسهمْ وَيَظُنُّونَ أَنَّهُمْ تَمَكَّنُوا مِنْ مُرَادهمْ . قَالَ مَعْنَاهُ اِبْن عَبَّاس وَغَيْره . وَالْحَرْد الْقَصْد . حَرَدَ يَحْرِد ( بِالْكَسْرِ ) حَرْدًا قَصَدَ . تَقُول : حَرَدْت حَرْدك ; أَيْ قَصَدْت قَصْدَك . وَمِنْهُ قَوْل الرَّاجِز : أَقْبَلَ سَيْلٌ جَاءَ مِنْ عِنْد اللَّه يَحْرِد حَرْد الْجَنَّة الْمُغِلَّهْ أَنْشَدَهُ النَّحَّاس : قَدْ جَاءَ سَيْل جَاءَ مِنْ أَمْر اللَّه يَحْرِد حَرْد الْجَنَّة الْمُغِلَّهْ قَالَ الْمُبَرِّد : الْمُغِلَّة ذَات الْغَلَّة . وَقَالَ غَيْره : الْمُغِلَّة الَّتِي يَجْرِي الْمَاء فِي غُلَلهَا أَيْ فِي أُصُولهَا . وَمِنْهُ تَغَلَّلَتْ بِالْغَالِيَةِ . وَمِنْهُ تَغَلَّيْت , أَبْدَلَ مِنْ اللَّام يَاء . وَمَنْ قَالَ تَغَلَّفَتْ فَمَعْنَاهُ عِنْده جَعَلْتهَا غِلَافًا . وَقَالَ قَتَادَة وَمُجَاهِد : &quot; عَلَى حَرْد &quot; أَيْ عَلَى جَدّ . الْحَسَن : عَلَى حَاجَة وَفَاقَة . وَقَالَ أَبُو عُبَيْدَة وَالْقُتَيْبِيّ : عَلَى حَرْد عَلَى مَنْع ; مِنْ قَوْلهمْ حَارَدَتْ الْإِبِل حِرَادًا أَيْ قَلَّتْ أَلْبَانهَا . وَالْحُرُود مِنْ النُّوق الْقَلِيلَة الدَّرّ . وَحَارَدَتْ السَّنَة قَلَّ مَطَرهَا وَخَيْرهَا . وَقَالَ السُّدِّيّ وَسُفْيَان : &quot; عَلَى حَرْد &quot; عَلَى غَضَب . وَالْحَرْد الْغَضَب . قَالَ أَبُو نَصْر أَحْمَد بْن حَاتِم صَاحِب الْأَصْمَعِيّ : وَهُوَ مُخَفَّف ; وَأَنْشَدَ شِعْرًا : إِذَا جِيَاد الْخَيْل جَاءَتْ تَرْدِي مَمْلُوءَة مِنْ غَضَب وَحَرَدِ وَقَالَ اِبْن السِّكِّيت : وَقَدْ يُحَرَّك ; تَقُول مِنْهُ : حُرِدَ ( بِالْكَسْرِ ) حَرْدًا , فَهُوَ حَارِد وَحَرْدَان . وَمِنْهُ قِيلَ : أَسَد حَارِد , وَلُيُوث حَوَارِد . وَقِيلَ : &quot; عَلَى حَرْد &quot; عَلَى اِنْفِرَاد . يُقَال : حَرَدَ يَحْرِد حُرُودًا ; أَيْ تَنَحَّى عَنْ قَوْمه وَنَزَلَ مُنْفَرِدًا وَلَمْ يُخَالِطهُمْ . وَقَالَ أَبُو زَيْد : رَجُل حَرِيد مِنْ قَوْم حُرَدَاء . وَقَدْ حَرَدَ يَحْرِد حُرُودًا ; إِذَا تَرَكَ قَوْمَهُ وَتَحَوَّل عَنْهُمْ . وَكَوْكَب حَرِيد ; أَيْ مُعْتَزِل عَنْ الْكَوَاكِب . قَالَ الْأَصْمَعِيّ : رَجُل حَرِيد ; أَيْ فَرِيد وَحِيد . قَالَ وَالْمُنْحَرِد الْمُنْفَرِد فِي لُغَة هُذَيْل . وَأَنْشَدَ لِأَبِي ذُؤَيْب : كَأَنَّهُ كَوْكَب فِي الْجَوّ مُنْحَرِد وَرَوَاهُ أَبُو عَمْرو بِالْجِيمِ , وَفَسَّرَهُ : مُنْفَرِد . قَالَ : وَهُوَ سُهَيْل . وَقَالَ الْأَزْهَرِيّ : حَرْد اِسْم قَرْيَتهمْ . السُّدِّيّ : اِسْم جَنَّتهمْ ; وَفِيهِ لُغَتَانِ : حَرْد وَحَرَد . وَقَرَأَ الْعَامَّة بِالْإِسْكَانِ . وَقَرَأَ أَبُو الْعَالِيَة وَابْن السَّمَيْقَع بِالْفَتْحِ ; وَهُمَا لُغَتَانِ . وَمَعْنَى &quot; قَادِرِينَ &quot; قَدْ قَدَّرُوا أَمْرهمْ وَبَنَوْا عَلَيْهِ ; قَالَهُ الْفَرَّاء . وَقَالَ قَتَادَة : قَادِرِينَ عَلَى جَنَّتهمْ عِنْدَ أَنْفُسهمْ . وَقَالَ الشَّعْبِيّ : &quot; قَادِرِينَ &quot; يَعْنِي عَلَى الْمَسَاكِين . وَقِيلَ : مَعْنَاهُ مِنْ الْوُجُود ; أَيْ مَنَعُوا وَهُمْ وَاجِدُونَ .';
$t[26] = 'أَيْ لَمَّا رَأَوْهَا مُحْتَرِقَة لَا شَيْء فِيهَا قَدْ صَارَتْ كَاللَّيْلِ الْأَسْوَد يَنْظُرُونَ إِلَيْهَا كَالرَّمَادِ , أَنْكَرُوهَا وَشَكُّوا فِيهَا . وَقَالَ بَعْضهمْ لِبَعْضٍ : &quot; إِنَّا لَضَالُّونَ &quot; أَيْ ضَلَلْنَا الطَّرِيقَ إِلَى جَنَّتنَا ; قَالَهُ قَتَادَة . وَقِيلَ : أَيْ إِنَّا لَضَالُّونَ عَنْ الصَّوَاب فِي غُدُوّنَا عَلَى نِيَّة مَنْع الْمَسَاكِين ; فَلِذَلِكَ عُوقِبْنَا .';
$t[27] = 'أَيْ حُرِمْنَا جَنَّتنَا بِمَا صَنَعْنَا . رَوَى أَسْبَاط عَنْ اِبْن مَسْعُود قَالَ : قَالَ رَسُول اللَّه صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ : ( إِيَّاكُمْ وَالْمَعَاصِي إِنَّ الْعَبْدَ لَيُذْنِب الذَّنْبَ فَيُحْرَم بِهِ رِزْقًا كَانَ هُيِّئَ لَهُ - ثُمَّ تَلَا - &quot; فَطَافَ عَلَيْهَا طَائِف مِنْ رَبّك &quot; [ الْقَلَم : 19 ] ) الْآيَتَيْنِ .';
$t[28] = 'أَيْ أَمْثَلهمْ وَأَعْدَلهمْ وَأَعْقَلهمْ .


أَيْ هَلَّا تَسْتَثْنُونَ . وَكَانَ اِسْتِثْنَاؤُهُمْ تَسْبِيحًا ; قَالَهُ مُجَاهِد وَغَيْره . وَهَذَا يَدُلّ عَلَى أَنَّ هَذَا الْأَوْسَط كَانَ أَمَرَهُمْ بِالِاسْتِثْنَاءِ فَلَمْ يُطِيعُوهُ . قَالَ أَبُو صَالِح : كَانَ اِسْتِثْنَاؤُهُمْ سُبْحَانَ اللَّه . فَقَالَ لَهُمْ : هَلَّا تُسَبِّحُونَ اللَّهَ ; أَيْ تَقُولُونَ سُبْحَانَ اللَّه وَتَشْكُرُونَهُ عَلَى مَا أَعْطَاكُمْ . قَالَ النَّحَّاس : أَصْل التَّسْبِيح التَّنْزِيه لِلَّهِ عَزَّ وَجَلَّ ; فَجَعَلَ مُجَاهِد التَّسْبِيح فِي مَوْضِع إِنْ شَاءَ اللَّه ; لِأَنَّ الْمَعْنَى تَنْزِيه اللَّه عَزَّ وَجَلَّ أَنْ يَكُونَ شَيْء إِلَّا بِمَشِيئَتِهِ . وَقِيلَ : هَلَّا تَسْتَغْفِرُونَهُ مِنْ فِعْلكُمْ وَتَتُوبُونَ إِلَيْهِ مِنْ خُبْث نِيَّتكُمْ ; فَإِنَّ أَوْسَطَهُمْ قَالَ لَهُمْ حِينَ عَزَمُوا عَلَى ذَلِكَ وَذَكَّرَهُمْ اِنْتِقَامَهُ مِنْ الْمُجْرِمِينَ';
$t[29] = 'اِعْتَرَفُوا بِالْمَعْصِيَةِ وَنَزَّهُوا اللَّه عَنْ أَنْ يَكُونَ ظَالِمًا فِيمَا فَعَلَ . قَالَ اِبْن عَبَّاس فِي قَوْلهمْ : &quot; سُبْحَانَ رَبّنَا &quot; أَيْ نَسْتَغْفِر اللَّهَ مِنْ ذَنْبنَا .


لِأَنْفُسِنَا فِي مَنْعنَا الْمَسَاكِين .';
$t[30] = 'أَيْ يَلُوم هَذَا هَذَا فِي الْقَسَم وَمَنْع الْمَسَاكِين , وَيَقُول : بَلْ أَنْتَ أَشَرْت عَلَيْنَا بِهَذَا .';
$t[31] = 'أَيْ عَاصِينَ بِمَنْعِ حَقّ الْفُقَرَاء وَتَرْك الِاسْتِثْنَاء . وَقَالَ اِبْن كَيْسَان : طَغَيْنَا نِعَم اللَّه فَلَمْ نَشْكُرهَا كَمَا شَكَرَهَا آبَاؤُنَا مِنْ قَبْل .';
$t[32] = 'تَعَاقَدُوا وَقَالُوا : إِنْ أَبْدَلَنَا اللَّه خَيْرًا مِنْهَا لَنَصْنَعَنَّ كَمَا صَنَعَتْ آبَاؤُنَا ; فَدَعَوْا اللَّهَ وَتَضَرَّعُوا فَأَبْدَلَهُمْ اللَّه مِنْ لَيْلَتهمْ مَا هُوَ خَيْر مِنْهَا , وَأَمَرَ جِبْرِيل أَنْ يَقْتَلِع تِلْكَ الْجَنَّة الْمُحْتَرِقَة فَيَجْعَلهَا بِزُغَر مِنْ أَرْض الشَّام , وَيَأْخُذ مِنْ الشَّام جَنَّة فَيَجْعَلهَا مَكَانهَا . وَقَالَ اِبْن مَسْعُود : إِنَّ الْقَوْمَ أَخْلَصُوا وَعَرَفَ اللَّه مِنْهُمْ صِدْقهمْ فَأَبْدَلَهُمْ جَنَّة يُقَال لَهَا الْحَيَوَان , فِيهَا عِنَب يَحْمِل الْبَغْل مِنْهَا عُنْقُودًا وَاحِدًا . وَقَالَ الْيَمَانِيّ أَبُو خَالِد : دَخَلْت تِلْكَ الْجَنَّة فَرَأَيْت كُلّ عُنْقُود مِنْهَا كَالرَّجُلِ الْأَسْوَد الْقَائِم . وَقَالَ الْحَسَن : قَوْل أَهْل الْجَنَّة


لَا أَدْرِي إِيمَانًا كَانَ ذَلِكَ مِنْهُمْ أَوْ عَلَى حَدّ مَا يَكُون مِنْ الْمُشْرِكِينَ إِذَا أَصَابَتْهُمْ الشِّدَّة ; فَيُوقَف فِي كَوْنهمْ مُؤْمِنِينَ . وَسُئِلَ قَتَادَة عَنْ أَصْحَاب الْجَنَّة : أَهُمْ مِنْ أَهْل الْجَنَّة أَمْ مِنْ أَهْل النَّار ؟ فَقَالَ : لَقَدْ كَلَّفَتْنِي تَعَبًا . وَالْمُعْظَم يَقُولُونَ : إِنَّهُمْ تَابُوا وَأَخْلَصُوا ; حَكَاهُ الْقُشَيْرِيّ . وَقِرَاءَة الْعَامَّة &quot; يُبْدِلنَا &quot; بِالتَّخْفِيفِ . وَقَرَأَ أَهْل الْمَدِينَة وَأَبُو عَمْرو بِالتَّشْدِيدِ , وَهُمَا لُغَتَانِ . وَقِيلَ : التَّبْدِيل تَغْيِير الشَّيْء أَوْ تَغْيِير حَاله وَعَيْن الشَّيْء قَائِم . وَالْإِبْدَال رَفْع الشَّيْء وَوَضْع آخَرَ مَكَانَهُ . وَقَدْ مَضَى فِي سُورَة &quot; النِّسَاء &quot; الْقَوْل فِي هَذَا .';
$t[33] = 'أَيْ عَذَاب الدُّنْيَا وَهَلَاك الْأَمْوَال ; عَنْ اِبْن زَيْد . وَقِيلَ : إِنَّ هَذَا وَعْظ لِأَهْلِ مَكَّةَ بِالرُّجُوعِ إِلَى اللَّه لَمَّا اِبْتَلَاهُمْ بِالْجَدْبِ لِدُعَاءِ النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ , أَيْ كَفِعْلِنَا بِهِمْ نَفْعَل بِمَنْ تَعَدَّى حُدُودَنَا فِي الدُّنْيَا


وَقَالَ اِبْن عَبَّاس : هَذَا مَثَل لِأَهْلِ مَكَّةَ حِينَ خَرَجُوا إِلَى بَدْر وَحَلَفُوا لَيَقْتُلُنَّ مُحَمَّدًا صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ وَأَصْحَابه , وَلَيَرْجِعُنَّ إِلَى مَكَّةَ حَتَّى يَطُوفُوا بِالْبَيْتِ وَيَشْرَبُوا الْخَمْرَ , وَتَضْرِب الْقَيْنَات عَلَى رُءُوسهمْ ; فَأَخْلَفَ اللَّه ظَنَّهُمْ وَأُسِرُوا وَقُتِلُوا وَانْهَزَمُوا كَأَهْلِ هَذِهِ الْجَنَّة لَمَّا خَرَجُوا عَازِمِينَ عَلَى الصِّرَام فَخَابُوا . ثُمَّ قِيلَ : إِنَّ الْحَقَّ الَّذِي مَنَعَهُ أَهْل الْجَنَّة الْمَسَاكِين يَحْتَمِل أَنَّهُ كَانَ وَاجِبًا عَلَيْهِمْ , وَيَحْتَمِل أَنَّهُ كَانَ تَطَوُّعًا ; وَالْأَوَّل أَظْهَر , وَاَللَّه أَعْلَم . وَقِيلَ : السُّورَة مَكِّيَّة ; فَبَعْد حَمْل الْآيَة عَلَى مَا أَصَابَ أَهْل مَكَّة مِنْ الْقَحْط , وَعَلَى قِتَال بَدْر .';
$t[34] = 'تَقَدَّمَ الْقَوْل فِيهِ ; أَيْ إِنَّ لِلْمُتَّقِينَ فِي الْآخِرَة جَنَّات لَيْسَ فِيهَا إِلَّا التَّنَعُّم الْخَالِص , لَا يَشُوبهُ مَا يُنَغِّصهُ كَمَا يَشُوب جَنَّات الدُّنْيَا . وَكَانَ صَنَادِيد قُرَيْش يَرَوْنَ وُفُور حَظّهمْ مِنْ الدُّنْيَا وَقِلَّة حُظُوظ الْمُسْلِمِينَ مِنْهَا ; فَإِذَا سَمِعُوا بِحَدِيثِ الْآخِرَة وَمَا وَعَدَ اللَّه الْمُؤْمِنِينَ قَالُوا : إِنْ صَحَّ أَنَّا نُبْعَث كَمَا يَزْعُم مُحَمَّد وَمَنْ مَعَهُ لَمْ يَكُنْ حَالنَا وَحَالهمْ إِلَّا مِثْل مَا هِيَ فِي الدُّنْيَا , وَإِلَّا لَمْ يَزِيدُوا عَلَيْنَا وَلَمْ يَفْضُلُونَا , وَأَقْصَى أَمْرهمْ أَنْ يُسَاوُونَا .';
$t[35] = 'أَيْ كَالْكَفَّارِ . وَقَالَ اِبْن عَبَّاس وَغَيْره : قَالَتْ كُفَّار مَكَّة : إِنَّا نُعْطَى فِي الْآخِرَة خَيْرًا مِمَّا تُعْطَوْنَ ; فَنَزَلَتْ &quot; أَفَنَجْعَل الْمُسْلِمِينَ كَالْمُجْرِمِينَ &quot; .';
$t[36] = 'هَذَا الْحُكْم الْأَعْوَج ; كَأَنَّ أَمْر الْجَزَاء مُفَوَّض إِلَيْكُمْ حَتَّى تُحْكَمُوا فِيهِ بِمَا شِئْتُمْ أَنَّ لَكُمْ مِنْ الْخَيْر مَا لِلْمُسْلِمِينَ .';
$t[37] = 'أَيْ لَكُمْ كِتَاب تَجِدُونَ فِيهِ الْمُطِيع كَالْعَاصِي .';
$t[38] = 'تَخْتَارُونَ وَتَشْتَهُونَ . وَالْمَعْنَى أَنَّ لَكُمْ ( بِالْفَتْحِ ) وَلَكِنَّهُ كُسِرَ لِدُخُولِ اللَّام ; تَقُول عَلِمْت أَنَّك عَاقِل ( بِالْفَتْحِ ) , وَعَلِمْت إِنَّك لَعَاقِل ( بِالْكَسْرِ ) . فَالْعَامِل فِي &quot; إِنَّ لَكُمْ فِيهِ لَمَا تَخَيَّرُونَ &quot; &quot; تَدْرُسُونَ &quot; فِي الْمَعْنَى . وَمَنَعَتْ اللَّام مِنْ فَتْح &quot; إِنَّ &quot; . وَقِيلَ : تَمَّ الْكَلَام عِنْد قَوْله : &quot; تَدْرُسُونَ &quot; ثُمَّ اِبْتَدَأَ فَقَالَ : &quot; إِنَّ لَكُمْ فِيهِ لَمَا تَخَيَّرُونَ &quot; أَيْ إِنَّ لَكُمْ فِي هَذَا الْكِتَاب إِذًا مَا تَخَيَّرُونَ ; أَيْ لَيْسَ لَكُمْ ذَلِكَ . وَالْكِنَايَة فِي &quot; فِيهِ &quot; الْأُولَى وَالثَّانِيَة رَاجِعَة إِلَى الْكِتَاب .';
$t[39] = 'أَيْ عُهُود وَمَوَاثِيق .


مُؤَكَّدَة . وَالْبَالِغَة الْمُؤَكَّدَة بِاَللَّهِ تَعَالَى . أَيْ أَمْ لَكُمْ عُهُود عَلَى اللَّه تَعَالَى اِسْتَوْثَقْتُمْ بِهَا فِي أَنْ يُدْخِلَكُمْ الْجَنَّةَ .


كُسِرَتْ &quot; إِنَّ &quot; لِدُخُولِ اللَّام فِي الْخَبَر . وَهِيَ مِنْ صِلَة &quot; أَيْمَان &quot; , وَالْمَوْضِع النَّصْب وَلَكِنْ كُسِرَتْ لِأَجْلِ اللَّام ; تَقُول : حَلَفْت إِنَّ لَك لَكَذَا . وَقِيلَ : تَمَّ الْكَلَام عِنْدَ قَوْله : &quot; إِلَى يَوْم الْقِيَامَة &quot; ثُمَّ قَالَ : &quot; إِنَّ لَكُمْ لَمَا تَحْكُمُونَ &quot; إِذًا ; أَيْ لَيْسَ الْأَمْر كَذَلِكَ . وَقَرَأَ اِبْن هُرْمُز &quot; أَيْنَ لَكُمْ فِيهِ لَمَا تَخَيَّرُونَ &quot; &quot; أَيْنَ لَكُمْ لَمَا تَحْكُمُونَ &quot; ; بِالِاسْتِفْهَامِ فِيهِمَا جَمِيعًا . وَقَرَأَ الْحَسَن الْبَصْرِيّ &quot; بَالِغَة &quot; بِالنَّصْبِ عَلَى الْحَال ; إِمَّا مِنْ الضَّمِير فِي &quot; لَكُمْ &quot; لِأَنَّهُ خَبَر عَنْ &quot; أَيْمَان &quot; فَفِيهِ ضَمِير مِنْهُ . وَإِمَّا مِنْ الضَّمِير فِي &quot; عَلَيْنَا &quot; إِنْ قَدَّرْت &quot; عَلَيْنَا &quot; وَصْفًا لِلْأَيْمَانِ لَا مُتَعَلِّقًا بِنَفْسِ الْأَيْمَان ; لِأَنَّ فِيهِ ضَمِيرًا مِنْهُ , كَمَا يَكُون إِذَا كَانَ خَبَرًا عَنْهُ . وَيَجُوز أَنْ يَكُون حَالًا مِنْ &quot; أَيْمَان &quot; وَإِنْ كَانَتْ نَكِرَة , كَمَا أَجَازُوا نَصْب &quot; حَقًّا &quot; عَلَى الْحَال مِنْ &quot; مَتَاع &quot; فِي قَوْله تَعَالَى : &quot; مَتَاع بِالْمَعْرُوفِ حَقًّا عَلَى الْمُتَّقِينَ &quot; [ الْبَقَرَة : 241 ] . وَقَرَأَ الْعَامَّة &quot; بَالِغَةٌ &quot; بِالرَّفْعِ نَعْت &quot; لِلْأَيْمَانِ &quot; .';
$t[40] = 'أَيْ سَلْ يَا مُحَمَّد هَؤُلَاءِ الْمُتَقَوِّلِينَ عَلَيَّ : أَيّهمْ كَفِيل بِمَا تَقَدَّمَ ذِكْره . وَهُوَ أَنَّ لَهُمْ مِنْ الْخَيْر مَا لِلْمُسْلِمِينَ . وَالزَّعِيم : الْكَفِيل وَالضَّمِين ; قَالَهُ اِبْن عَبَّاس وَقَتَادَة . وَقَالَ اِبْن كَيْسَان : الزَّعِيم هُنَا الْقَائِم بِالْحُجَّةِ وَالدَّعْوَى . وَقَالَ الْحَسَن : الزَّعِيم الرَّسُول .';
$t[41] = 'أَيْ أَلَهُمْ وَالْمِيم صِلَة . &quot; شُرَكَاء &quot; أَيْ شُهَدَاء .


يَشْهَدُونَ عَلَى مَا زَعَمُوا .


فِي دَعْوَاهُمْ . وَقِيلَ : أَيْ فَلْيَأْتُوا بِشُرَكَائِهِمْ إِنْ أَمْكَنَهُمْ ; فَهُوَ أَمْر مَعْنَاهُ التَّعْجِيز .';
$t[42] = 'يَجُوز أَنْ يَكُونَ الْعَامِل فِي &quot; يَوْم &quot; &quot; فَلْيَأْتُوا &quot; أَيْ فَلْيَأْتُوا بِشُرَكَائِهِمْ يَوْم يُكْشَف عَنْ سَاق لِيَشْفَعَ الشُّرَكَاء لَهُمْ . وَيَجُوز أَنْ يَنْتَصِبَ بِإِضْمَارِ فِعْل , أَيْ اُذْكُرْ يَوْمَ يُكْشَف عَنْ سَاق ; فَيُوقَف عَلَى &quot; صَادِقِينَ &quot; وَلَا يُوقَف عَلَيْهِ عَلَى التَّقْدِير الْأَوَّل . وَقُرِئَ &quot; يَوْمَ نَكْشِف &quot; بِالنُّونِ . &quot; وَقَرَأَ &quot; اِبْن عَبَّاس &quot; يَوْم تَكْشِف عَنْ سَاق &quot; بِتَاءِ مُسَمَّى الْفَاعِل ; أَيْ تَكْشِف الشِّدَّة أَوْ الْقِيَامَة . عَنْ سَاقهَا ; كَقَوْلِهِمْ : شَمَّرَتْ الْحَرْب عَنْ سَاقهَا . قَالَ الشَّاعِر : فَتَى الْحَرْب إِنْ عَضَّتْ بِهِ الْحَرْب عَضَّهَا وَإِنْ شَمَّرَتْ عَنْ سَاقهَا الْحَرْب شَمَّرَا وَقَالَ الرَّاجِز : قَدْ كَشَفَتْ عَنْ سَاقهَا فَشُدُّوا وَجَدَّتْ الْحَرْب بِكُمْ فَجِدُّوا وَقَالَ آخَر : عَجِبْت مِنْ نَفْسِي وَمِنْ إِشْفَاقهَا وَمِنْ طَرَّاد الطَّيْر عَنْ أَرْزَاقهَا فِي سَنَة قَدْ كَشَفَتْ عَنْ سَاقهَا حَمْرَاء تَبْرِي اللَّحْمَ عَنْ عُرَاقهَا وَقَالَ آخَر : كَشَفَتْ لَهُمْ عَنْ سَاقهَا وَبَدَا مِنْ الشَّرّ الصُّرَاحْ وَعَنْ اِبْن عَبَّاس أَيْضًا وَالْحَسَن وَأَبِي الْعَالِيَة &quot; تُكْشَف &quot; بِتَاءِ غَيْر مُسَمَّى الْفَاعِل . وَهَذِهِ الْقِرَاءَة رَاجِعَة إِلَى مَعْنَى &quot; يُكْشَف &quot; وَكَأَنَّهُ قَالَ : يَوْم تَكْشِف الْقِيَامَة عَنْ شِدَّة . وَقُرِئَ &quot; يَوْم تُكْشِف &quot; بِالتَّاءِ الْمَضْمُومَة وَكَسْر الشِّين ; مِنْ أَكْشَفَ إِذَا دَخَلَ فِي الْكَشْف . وَمِنْهُ : أَكْشَفَ الرَّجُل فَهُوَ مُكْشَف ; إِذَا اِنْقَلَبَتْ شَفَته الْعُلْيَا . وَذَكَرَ اِبْن الْمُبَارَك قَالَ : أَخْبَرَنَا أُسَامَة بْن زَيْد عَنْ عِكْرِمَة عَنْ اِبْن عَبَّاس فِي قَوْله تَعَالَى : &quot; يَوْم يُكْشَف عَنْ سَاق &quot; قَالَ : عَنْ كَرْب وَشِدَّة . أَخْبَرَنَا اِبْن جُرَيْج عَنْ مُجَاهِد قَالَ : شِدَّة الْأَمْر وَجَدّه . وَقَالَ مُجَاهِد : قَالَ اِبْن عَبَّاس هِيَ أَشَدّ سَاعَة فِي يَوْم الْقِيَامَة . وَقَالَ أَبُو عُبَيْدَة : إِذَا اِشْتَدَّ الْحَرْب وَالْأَمْر قِيلَ : كَشَفَ الْأَمْر عَنْ سَاقه . وَالْأَصْل فِيهِ أَنَّ مَنْ وَقَعَ فِي شَيْء يَحْتَاج فِيهِ إِلَى الْجَدّ شَمَّرَ عَنْ سَاقه ; فَاسْتُعِيرَ السَّاق وَالْكَشْف عَنْهَا فِي مَوْضِع الشِّدَّة . وَقِيلَ : سَاق الشَّيْءَ أَصْله الَّذِي بِهِ قِوَامه ; كَسَاقِ الشَّجَرَة وَسَاق الْإِنْسَان . أَيْ يَوْم يُكْشَف عَنْ أَصْل الْأَمْر فَتَظْهَر حَقَائِق الْأُمُور وَأَصْلهَا . وَقِيلَ : يُكْشَف عَنْ سَاق جَهَنَّمَ . وَقِيلَ : عَنْ سَاق الْعَرْش . وَقِيلَ : يُرِيد وَقْت اِقْتِرَاب الْأَجَل وَضَعْف الْبَدَن ; أَيْ يَكْشِف الْمَرِيض عَنْ سَاقه لِيَبْصُر ضَعْفه , وَيَدْعُوهُ الْمُؤَذِّن إِلَى الصَّلَاة فَلَا يُمْكِنهُ أَنْ يَقُومَ وَيَخْرُج . فَأَمَّا مَا رُوِيَ أَنَّ اللَّهَ يَكْشِفُ عَنْ سَاقه فَإِنَّهُ عَزَّ وَجَلَّ يَتَعَالَى عَنْ الْأَعْضَاء وَالتَّبْعِيض وَأَنْ يَكْشِفَ وَيَتَغَطَّى . وَمَعْنَاهُ أَنْ يَكْشِفَ عَنْ الْعَظِيم مِنْ أَمْره . وَقِيلَ : يَكْشِف عَنْ نُوره عَزَّ وَجَلَّ . وَرَوَى أَبُو مُوسَى عَنْ النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فِي قَوْله تَعَالَى : &quot; عَنْ سَاق &quot; قَالَ : ( يَكْشِف عَنْ نُور عَظِيم يَخِرُّونَ لَهُ سُجَّدًا ) . وَقَالَ أَبُو اللَّيْث السَّمَرْقَنْدِيّ فِي تَفْسِيره : حَدَّثَنَا الْخَلِيل بْن أَحْمَد قَالَ حَدَّثَنَا اِبْن مَنِيع قَالَ حَدَّثَنَا هُدْبَة قَالَ حَدَّثَنَا حَمَّاد بْن سَلَمَة عَنْ عَدِيّ بْن زَيْد عَنْ عُمَارَة الْقُرَشِيّ عَنْ أَبِي بُرْدَة عَنْ أَبِي مُوسَى قَالَ حَدَّثَنِي أَبِي قَالَ : سَمِعْت رَسُولَ اللَّه صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَقُول : ( إِذَا كَانَ يَوْم الْقِيَامَة مُثِّلَ لِكُلِّ قَوْم مَا كَانُوا يَعْبُدُونَ فِي الدُّنْيَا فَيَذْهَب كُلّ قَوْم إِلَى مَا كَانُوا يَعْبُدُونَ وَيَبْقَى أَهْل التَّوَحُّد فَيُقَال لَهُمْ مَا تَنْتَظِرُونَ وَقَدْ ذَهَبَ النَّاس فَيَقُولُونَ إِنَّ لَنَا رَبًّا كُنَّا نَعْبُدهُ فِي الدُّنْيَا وَلَمْ نَرَهُ - قَالَ - وَتَعْرِفُونَهُ إِذَا رَأَيْتُمُوهُ فَيَقُولُونَ نَعَمْ فَيُقَال فَكَيْفَ تَعْرِفُونَهُ وَلَمْ تَرَوْهُ قَالُوا إِنَّهُ لَا شَبِيه لَهُ فَيَكْشِف لَهُمْ الْحِجَابَ فَيَنْظُرُونَ إِلَى اللَّه تَعَالَى فَيَخِرُّونَ لَهُ سُجَّدًا وَتَبْقَى أَقْوَام ظُهُورهمْ مِثْل صَيَاصِي الْبَقَر فَيَنْظُرُونَ إِلَى اللَّه تَعَالَى فَيُرِيدُونَ السُّجُودَ فَلَا يَسْتَطِيعُونَ فَذَلِكَ قَوْله تَعَالَى : &quot; يَوْم يُكْشَف عَنْ سَاق وَيُدْعَوْنَ إِلَى السُّجُود فَلَا يَسْتَطِيعُونَ &quot; فَيَقُول اللَّه تَعَالَى عِبَادِي اِرْفَعُوا رُءُوسَكُمْ فَقَدْ جَعَلْت بَدَل كُلّ رَجُل مِنْكُمْ رَجُلًا مِنْ الْيَهُود وَالنَّصَارَى فِي النَّار ) . قَالَ أَبُو بُرْدَة : فَحَدَّثْت بِهَذَا الْحَدِيث عُمَرَ بْن عَبْد الْعَزِيز فَقَالَ : اللَّه الَّذِي لَا إِلَهَ إِلَّا هُوَ لَقَدْ حَدَّثَك أَبُوك بِهَذَا الْحَدِيث ؟ فَحَلَفَ لَهُ ثَلَاثَةَ أَيْمَان ; فَقَالَ عُمَر : مَا سَمِعْت فِي أَهْل التَّوْحِيد حَدِيثًا هُوَ أَحَبّ إِلَيَّ مِنْ هَذَا . وَقَالَ قَيْس بْن السَّكَن : حَدَّثَ عَبْد اللَّه بْن مَسْعُود عِنْد عُمَر بْن الْخَطَّاب فَقَالَ : إِذَا كَانَ يَوْم الْقِيَامَة قَامَ النَّاس لِرَبِّ الْعَالَمِينَ أَرْبَعِينَ عَامًا شَاخِصَة أَبْصَارهمْ إِلَى السَّمَاء , حُفَاة عُرَاة يُلْجِمهُمْ الْعَرَق , فَلَا يُكَلِّمهُمْ اللَّه وَلَا يَنْظُر إِلَيْهِمْ أَرْبَعِينَ عَامًا , ثُمَّ يُنَادِي مُنَادٍ : أَيّهَا النَّاس , أَلَيْسَ عَدْلًا مِنْ رَبّكُمْ الَّذِي خَلَقَكُمْ وَصَوَّرَكُمْ وَأَمَاتَكُمْ وَأَحْيَاكُمْ ثُمَّ عَبَدْتُمْ غَيْرَهُ أَنْ يُوَلِّيَ كُلّ قَوْم مَا تَوَلَّوْا ؟ قَالُوا : نَعَمْ . قَالَ : فَيَرْفَع لِكُلِّ قَوْم مَا كَانُوا يَعْبُدُونَ مِنْ دُون اللَّه فَيَتْبَعُونَهَا حَتَّى تَقْذِفهُمْ فِي النَّار , فَيَبْقَى الْمُسْلِمُونَ وَالْمُنَافِقُونَ فَيُقَال لَهُمْ : أَلَا تَذْهَبُونَ قَدْ ذَهَبَ النَّاس ؟ فَيَقُولُونَ حَتَّى يَأْتِيَنَا رَبّنَا ; فَيُقَال لَهُمْ : أَوَتَعْرِفُونَهُ ؟ فَيَقُولُونَ : إِنْ اِعْتَرَفَ لَنَا عَرَفْنَاهُ . قَالَ فَعِنْدَ ذَلِكَ يُكْشَف عَنْ سَاق وَيَتَجَلَّى لَهُمْ فَيَخِرّ مَنْ كَانَ يَعْبُدهُ مُخْلِصًا سَاجِدًا , وَيَبْقَى الْمُنَافِقُونَ لَا يَسْتَطِيعُونَ كَأَنَّ فِي ظُهُورهمْ السَّفَافِيد , فَيُذْهَب بِهِمْ إِلَى النَّار , وَيَدْخُل هَؤُلَاءِ الْجَنَّة ; فَذَلِكَ قَوْله تَعَالَى : &quot; وَيُدْعَوْنَ إِلَى السُّجُود فَلَا يَسْتَطِيعُونَ &quot; .';
$t[43] = 'أَيْ ذَلِيلَة مُتَوَاضِعَة ; وَنَصْبهَا عَلَى الْحَال .


وَذَلِكَ أَنَّ الْمُؤْمِنِينَ يَرْفَعُونَ رُءُوسَهُمْ وَوُجُوههمْ أَشَدّ بَيَاضًا مِنْ الثَّلْج . وَتَسْوَدّ وُجُوه الْمُنَافِقِينَ وَالْكَافِرِينَ حَتَّى تَرْجِعَ أَشَدّ سَوَادًا مِنْ الْقَار . قُلْت : مَعْنَى حَدِيث أَبِي مُوسَى وَابْن مَسْعُود ثَابِت فِي صَحِيح مُسْلِم مِنْ حَدِيث أَبِي سَعِيد الْخُدْرِيّ وَغَيْره .


أَيْ فِي الدُّنْيَا .


مُعَافُونَ أَصِحَّاء . قَالَ إِبْرَاهِيم التَّيْمِيّ : أَيْ يُدْعَوْنَ بِالْأَذَانِ وَالْإِقَامَة فَيَأْبَوْنَهُ . وَقَالَ سَعِيد بْن جُبَيْر : كَانُوا يَسْمَعُونَ حَيّ عَلَى الْفَلَاح فَلَا يُجِيبُونَ . وَقَالَ كَعْب الْأَحْبَار : وَاَللَّه مَا نَزَلَتْ هَذِهِ الْآيَة إِلَّا فِي الَّذِينَ يَتَخَلَّفُونَ عَنْ الْجَمَاعَات . وَقِيلَ : أَيْ بِالتَّكْلِيفِ الْمُوَجَّه عَلَيْهِمْ فِي الشَّرْع ; وَالْمَعْنَى مُتَقَارِب . وَقَدْ مَضَى فِي سُورَة &quot; الْبَقَرَة &quot; الْكَلَام فِي وُجُوب صَلَاة الْجَمَاعَة . وَكَانَ الرَّبِيع بْن خَيْثَم قَدْ فُلِجَ وَكَانَ يُهَادَى بَيْنَ الرَّجُلَيْنِ إِلَى الْمَسْجِد ; فَقِيلَ : يَا أَبَا يَزِيد , لَوْ صَلَّيْت فِي بَيْتك لَكَانَتْ لَك رُخْصَة . فَقَالَ : مَنْ سَمِعَ حَيّ عَلَى الْفَلَاح فَلْيُجِبْ وَلَوْ حَبْوًا . وَقِيلَ لِسَعِيدِ بْن الْمُسَيِّب : إِنَّ طَارِقًا يُرِيد قَتْلَك فَتَغَيَّبْ . فَقَالَ : أَبِحَيْثُ لَا يَقْدِر اللَّه عَلَيَّ ؟ فَقِيلَ لَهُ : اِجْلِسْ فِي بَيْتك . فَقَالَ : أَسْمَع حَيَّ عَلَى الْفَلَاح , فَلَا أُجِيب !';
$t[44] = 'أَيْ دَعْنِي .


&quot;مَنْ &quot; مَفْعُول مَعَهُ أَوْ مَعْطُوف عَلَى ضَمِير الْمُتَكَلِّم .


يَعْنِي الْقُرْآن ; قَالَهُ السُّدِّيّ . وَقِيلَ : يَوْم الْقِيَامَة . وَهَذَا تَسْلِيَة لِلنَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ ; أَيْ فَأَنَا أُجَازِيهِمْ وَأَنْتَقِم مِنْهُمْ .


مَعْنَاهُ سَنَأْخُذُهُمْ عَلَى غَفْلَة وَهُمْ لَا يَعْرِفُونَ ; فَعُذِّبُوا يَوْمَ بَدْر . وَقَالَ سُفْيَان الثَّوْرِيّ : نُسْبِغ عَلَيْهِمْ النِّعَم وَنُنْسِيهِمْ الشُّكْر . وَقَالَ الْحَسَن : كَمْ مُسْتَدْرَج بِالْإِحْسَانِ إِلَيْهِ , وَكَمْ مَفْتُون بِالثَّنَاءِ عَلَيْهِ , وَكَمْ مَغْرُور بِالسِّتْرِ عَلَيْهِ . وَقَالَ أَبُو رَوْق : أَيْ كُلَّمَا أَحْدَثُوا خَطِيئَة جَدَّدْنَا لَهُمْ نِعْمَة وَأَنْسَيْنَاهُمْ الِاسْتِغْفَارَ . وَقَالَ اِبْن عَبَّاس : سَنَمْكُرُ بِهِمْ . وَقِيلَ : هُوَ أَنْ نَأْخُذَهُمْ قَلِيلًا وَلَا نُبَاغِتَهُمْ . وَفِي حَدِيث ( أَنَّ رَجُلًا مِنْ بَنِي إِسْرَائِيل قَالَ يَا رَبّ كَمْ أَعْصِيك وَأَنْتَ لَا تُعَاقِبنِي - قَالَ - فَأَوْحَى اللَّه إِلَى نَبِيّ زَمَانهمْ أَنْ قُلْ لَهُ كَمْ مِنْ عُقُوبَة لِي عَلَيْك وَأَنْتَ لَا تَشْعُر . إِنَّ جُمُود عَيْنَيْك وَقَسَاوَة قَلْبك اِسْتِدْرَاج مِنِّي وَعُقُوبَة لَوْ عَقَلْت ) . وَالِاسْتِدْرَاج : تَرْك الْمُعَاجَلَة . وَأَصْله النَّقْل مِنْ حَال إِلَى حَال كَالتَّدَرُّجِ . وَمِنْهُ قِيلَ دَرَجَة ; وَهِيَ مَنْزِلَة بَعْد مَنْزِلَة . وَاسْتَدْرَجَ فُلَان فُلَانًا ; أَيْ اِسْتَخْرَجَ مَا عِنْدَهُ قَلِيلًا . وَيُقَال : دَرَجَهُ إِلَى كَذَا وَاسْتَدْرَجَهُ بِمَعْنًى ; أَيْ أَدْنَاهُ مِنْهُ عَلَى التَّدْرِيج فَتَدَرَّجَ هُوَ .';
$t[45] = 'أَيْ أُمْهِلهُمْ وَأُطِيل لَهُمْ الْمُدَّة . وَالْمُلَاوَة : الْمُدَّة مِنْ الدَّهْر . وَأَمْلَى اللَّه لَهُ أَيْ أَطَالَ لَهُ . وَالْمَلَوَانِ : اللَّيْل وَالنَّهَار . وَقِيلَ : &quot; وَأُمْلِي لَهُمْ &quot; أَيْ لَا أُعَاجِلهُمْ بِالْمَوْتِ ; وَالْمَعْنَى وَاحِد . وَقَدْ مَضَى فِي &quot; الْأَعْرَاف &quot; بَيَان هَذَا .


أَيْ إِنَّ عَذَابِي لَقَوِيّ شَدِيد فَلَا يَفُوتنِي أَحَد .';
$t[46] = 'عَادَ الْكَلَام إِلَى مَا تَقَدَّمَ مِنْ قَوْله تَعَالَى : &quot; أَمْ لَهُمْ شُرَكَاء &quot; [ الْقَلَم : 41 ] . أَيْ أَمْ تَلْتَمِس مِنْهُمْ ثَوَابًا عَلَى مَا تَدْعُوهُمْ إِلَيْهِ مِنْ الْإِيمَان بِاَللَّهِ ؟ فَهُمْ مِنْ غَرَامَة ذَلِكَ مُثْقَلُونَ لِمَا يَشُقّ عَلَيْهِمْ مِنْ بَذْل الْمَال ; أَيْ لَيْسَ عَلَيْهِمْ كُلْفَة , بَلْ يَسْتَوْلُونَ بِمُتَابَعَتِك عَلَى خَزَائِن الْأَرْض وَيَصِلُونَ إِلَى جَنَّات النَّعِيم .';
$t[47] = 'أَيْ عِلْم مَا غَابَ عَنْهُمْ .


وَقِيلَ : أَيَنْزِلُ عَلَيْهِمْ الْوَحْي بِهَذَا الَّذِي يَقُولُونَ . وَعَنْ اِبْن عَبَّاس : الْغَيْب هُنَا اللَّوْح الْمَحْفُوظ فَهُمْ يَكْتُبُونَ مِمَّا فِيهِ يُخَاصِمُونَك بِهِ , وَيَكْتُبُونَ أَنَّهُمْ أَفْضَل مِنْكُمْ , وَأَنَّهُمْ لَا يُعَاقَبُونَ . وَقِيلَ : &quot; يَكْتُبُونَ &quot; يَحْكُمُونَ لِأَنْفُسِهِمْ بِمَا يُرِيدُونَ .';
$t[48] = 'أَيْ لِقَضَاءِ رَبّك . وَالْحُكْم هُنَا الْقَضَاء . وَقِيلَ : فَاصْبِرْ عَلَى مَا حَكَمَ بِهِ عَلَيْك رَبّك مِنْ تَبْلِيغ الرِّسَالَة . وَقَالَ اِبْن بَحْر : فَاصْبِرْ لِنَصْرِ رَبّك . قَالَ قَتَادَة : أَيْ لَا تَعْجَل وَلَا تُغَاضِب فَلَا بُدّ مِنْ نَصْرك . وَقِيلَ : إِنَّهُ مَنْسُوخ بِآيَةِ السَّيْف .


يَعْنِي يُونُس عَلَيْهِ السَّلَام . أَيْ لَا تَكُنْ مِثْله فِي الْغَضَب وَالضَّجَر وَالْعَجَلَة . وَقَالَ قَتَادَة : إِنَّ اللَّهَ تَعَالَى يُعَزِّي نَبِيَّهُ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ وَيَأْمُرهُ بِالصَّبْرِ وَلَا يَعْجَل كَمَا عَجِلَ صَاحِب الْحُوت ; وَقَدْ مَضَى خَبَره فِي سُورَة &quot; يُونُس , وَالْأَنْبِيَاء , وَالصَّافَّات &quot; وَالْفَرْق بَيْنَ إِضَافَة ذِي وَصَاحِب فِي سُورَة &quot; يُونُس &quot; فَلَا مَعْنَى لِلْإِعَادَةِ .


أَيْ حِينَ دَعَا فِي بَطْن الْحُوت فَقَالَ : &quot; لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَك إِنِّي كُنْت مِنْ الظَّالِمِينَ &quot; [الْأَنْبِيَاء : 87 ] .


أَيْ مَمْلُوء غَمًّا . وَقِيلَ : كَرْبًا . الْأَوَّل قَوْل اِبْن عَبَّاس وَمُجَاهِد . وَالثَّانِي قَوْل عَطَاء وَأَبِي مَالِك . قَالَ الْمَاوَرْدِيّ : وَالْفَرْق بَيْنَهُمَا أَنَّ الْغَمَّ فِي الْقَلْب , وَالْكَرْب فِي الْأَنْفَاس . وَقِيلَ : مَكْظُوم مَحْبُوس . وَالْكَظْم الْحَبْس ; وَمِنْهُ قَوْلهمْ : فُلَان كَظَمَ غَيْظَهُ , أَيْ حَبَسَ غَضَبَهُ ; قَالَهُ اِبْن بَحْر . وَقِيلَ : إِنَّهُ الْمَأْخُوذ بِكَظْمِهِ وَهُوَ مَجْرَى النَّفَس ; قَالَهُ الْمُبَرِّد . وَقَدْ مَضَى هَذَا وَغَيْره فِي &quot; يُوسُف &quot; .';
$t[49] = 'قِرَاءَة الْعَامَّة &quot; تَدَارَكَهُ &quot; . وَقَرَأَ اِبْن هُرْمُز وَالْحَسَن &quot; تَدَّارَكهُ &quot; بِتَشْدِيدِ الدَّال ; وَهُوَ مُضَارِع أُدْغِمَتْ التَّاء مِنْهُ فِي الدَّال . وَهُوَ عَلَى تَقْدِير حِكَايَة الْحَال ; كَأَنَّهُ قَالَ : لَوْلَا أَنْ كَانَ يُقَال فِيهِ تَتَدَارَكهُ نِعْمَة . اِبْن عَبَّاس وَابْن مَسْعُود : &quot; تَدَارَكَتْهُ &quot; وَهُوَ خِلَاف الْمَرْسُوم . وَ &quot; تَدَارَكَهُ &quot; فِعْل مَاضٍ مُذَكَّر حُمِلَ عَلَى مَعْنَى النِّعْمَة ; لِأَنَّ تَأْنِيث النِّعْمَة غَيْر حَقِيقِيّ . وَ &quot; تَدَارَكَتْهُ &quot; عَلَى لَفْظهَا . وَاخْتُلِفَ فِي مَعْنَى النِّعْمَة هُنَا ; فَقِيلَ النُّبُوَّة ; قَالَهُ الضَّحَّاك . وَقِيلَ عِبَادَته إِلَتِي سَلَفَتْ ; قَالَهُ اِبْن جُبَيْر . وَقِيلَ : نِدَاؤُهُ &quot; لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَك إِنِّي كُنْت مِنْ الظَّالِمِينَ &quot; [ الْأَنْبِيَاء : 87 ] ; قَالَهُ اِبْن زَيْد . وَقِيلَ : نِعْمَة اللَّه عَلَيْهِ إِخْرَاجه مِنْ بَطْن الْحُوت ; قَالَهُ اِبْن بَحْر . وَقِيلَ : أَيْ رَحْمَة مِنْ رَبّه ; فَرَحِمَهُ وَتَابَ عَلَيْهِ .


أَيْ لَنُبِذَ مَذْمُومًا وَلَكِنَّهُ نُبِذَ سَقِيمًا غَيْرَ مَذْمُوم . وَمَعْنَى &quot; مَذْمُوم &quot; فِي قَوْل اِبْن عَبَّاس : مُلِيم . قَالَ بَكْر بْن عَبْد اللَّه : مُذْنِب . وَقِيلَ : &quot; مَذْمُوم &quot; مُبْعَد مِنْ كُلّ , خَيْر . وَالْعَرَاء : الْأَرْض الْوَاسِعَة الْفَضَاء الَّتِي لَيْسَ فِيهَا جَبَل وَلَا شَجَر يَسْتُر . وَقِيلَ : وَلَوْلَا فَضْل اللَّه عَلَيْهِ لَبَقِيَ فِي بَطْن الْحُوت إِلَى يَوْم الْقِيَامَة , ثُمَّ نُبِذَ بِعَرَاءِ الْقِيَامَة مَذْمُومًا . يَدُلّ عَلَيْهِ قَوْله تَعَالَى : &quot; فَلَوْلَا أَنَّهُ كَانَ مِنْ الْمُسَبِّحِينَ . لَلَبِثَ فِي بَطْنه إِلَى يَوْم يُبْعَثُونَ &quot; [ الصَّافَّات : 143 - 144 ] .';
$t[50] = 'أَيْ اِصْطَفَاهُ وَاخْتَارَهُ . &quot; فَجَعَلَهُ مِنْ الصَّالِحِينَ &quot; قَالَ اِبْن عَبَّاس : رَدَّ اللَّه إِلَيْهِ الْوَحْيَ , وَشَفَّعَهُ فِي نَفْسه وَفِي قَوْمه , وَقَبِلَ تَوْبَته , وَجَعَلَهُ مِنْ الصَّالِحِينَ بِأَنْ أَرْسَلَهُ إِلَى مِائَة أَلْف أَوْ يَزِيدُونَ .';
$t[51] = '&quot;إِنْ &quot; هِيَ الْمُخَفَّفَة مِنْ الثَّقِيلَة . &quot; لَيُزْلِقُونَكَ &quot; أَيْ يَعْتَانُونَكَ .

أَخْبَرَ بِشِدَّةِ عَدَاوَتهمْ النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ , وَأَرَادُوا أَنْ يُصِيبُوهُ بِالْعَيْنِ فَنَظَرَ إِلَيْهِ قَوْم مِنْ قُرَيْش وَقَالُوا : مَا رَأَيْنَا مِثْله وَلَا مِثْل حُجَجه . وَقِيلَ : كَانَتْ الْعَيْن فِي بَنِي أَسَد , حَتَّى إِنَّ الْبَقَرَةَ السَّمِينَةَ أَوْ النَّاقَة السَّمِينَةَ تَمُرّ بِأَحَدِهِمْ فَيُعَايِنهَا ثُمَّ يَقُول : يَا جَارِيَة , خُذِي الْمِكْتَل وَالدِّرْهَم فَأْتِينَا بِلَحْمِ هَذِهِ النَّاقَة , فَمَا تَبْرَح حَتَّى تَقَعَ لِلْمَوْتِ فَتُنْحَر . وَقَالَ الْكَلْبِيّ : كَانَ رَجُل مِنْ الْعَرَب يَمْكُث لَا يَأْكُل شَيْئًا يَوْمَيْنِ أَوْ ثَلَاثَة , ثُمَّ يَرْفَع جَانِبَ الْخِبَاء فَتَمُرّ بِهِ الْإِبِل أَوْ الْغَنَم فَيَقُول : لَمْ أَرَ كَالْيَوْمِ إِبِلًا وَلَا غَنَمًا أَحْسَنَ مِنْ هَذِهِ فَمَا تَذْهَب إِلَّا قَلِيلًا حَتَّى تَسْقُط مِنْهَا طَائِفَة هَالِكَة . فَسَأَلَ الْكُفَّار هَذَا الرَّجُل أَنْ يُصِيبَ لَهُمْ النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ بِالْعَيْنِ فَأَجَابَهُمْ ; فَلَمَّا مَرَّ النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ أَنْشَدَ : قَدْ كَانَ قَوْمك يَحْسِبُونَك سَيِّدًا وَإِخَال أَنَّك سَيِّد مَعْيُونُ فَعَصَمَ اللَّه نَبِيَّهُ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ وَنَزَلَتْ : &quot; وَإِنْ يَكَاد الَّذِينَ كَفَرُوا لَيُزْلِقُونَكَ &quot; . وَذَكَرَ نَحْوَهُ الْمَاوَرْدِيّ . وَأَنَّ الْعَرَبَ كَانَتْ إِذَا أَرَادَ أَحَدهمْ أَنْ يُصِيبَ أَحَدًا - يَعْنِي فِي نَفْسه وَمَالِهِ - تَجَوَّعَ ثَلَاثَةَ أَيَّام , ثُمَّ يَتَعَرَّض لِنَفْسِهِ وَمَالِهِ فَيَقُول : تَاللَّهِ مَا رَأَيْت أَقْوَى مِنْهُ وَلَا أَشْجَعَ وَلَا أَكْثَرَ مِنْهُ وَلَا أَحْسَنَ ; فَيُصِيبهُ بِعَيْنِهِ فَيَهْلِك هُوَ وَمَاله ; فَأَنْزَلَ اللَّه تَعَالَى هَذِهِ الْآيَة . قَالَ الْقُشَيْرِيّ : وَفِي هَذَا نَظَر ; لِأَنَّ الْإِصَابَةَ بِالْعَيْنِ إِنَّمَا تَكُون مَعَ الِاسْتِحْسَان وَالْإِعْجَاب لَا مَعَ الْكَرَاهِيَة وَالْبُغْض ; وَلِهَذَا قَالَ :


أَيْ يَنْسُبُونَك إِلَى الْجُنُون إِذَا رَأَوْك تَقْرَأ الْقُرْآنَ . قُلْت : أَقْوَال الْمُفَسِّرِينَ وَاللُّغَوِيِّينَ تَدُلّ عَلَى مَا ذَكَرْنَا , وَأَنَّ مُرَادَهُمْ بِالنَّظَرِ إِلَيْهِ قَتْله . وَلَا يَمْنَع كَرَاهَة الشَّيْء مِنْ أَنْ يُصَابَ بِالْعَيْنِ عَدَاوَة حَتَّى يَهْلِك . وَقَرَأَ اِبْن عَبَّاس وَابْن مَسْعُود وَالْأَعْمَش وَأَبُو وَائِل وَمُجَاهِد &quot; لَيُزْلِقُونَكَ &quot; أَيْ لَيُهْلِكُونَك . وَهَذِهِ قِرَاءَة عَلَى التَّفْسِير , مِنْ زَهِقَتْ نَفْسه وَأَزْهَقَهَا . وَقَرَأَ أَهْل الْمَدِينَة &quot; لَيَزْلِقُونَكَ &quot; بِفَتْحِ الْيَاء . وَضَمَّهَا الْبَاقُونَ ; وَهُمَا لُغَتَانِ بِمَعْنًى ; يُقَال : زَلَقَهُ يَزْلِقهُ وَأَزْلَقَهُ يُزْلِقهُ إِزْلَاقًا إِذَا نَحَّاهُ وَأَبْعَدَهُ . وَزَلَقَ رَأْسَهُ يَزْلِقهُ زَلْقًا إِذَا حَلَقَهُ . وَكَذَلِكَ أَزْلَقَهُ وَزَلَقَهُ تَزْلِيقًا . وَرَجُل زَلِق وَزُمَلِق - مِثَال هُدَبِد - وَزَمَالِق وَزُمَّلِق - بِتَشْدِيدِ الْمِيم - وَهُوَ الَّذِي يُنْزِل قَبْل أَنْ يُجَامِع ; حَكَاهُ الْجَوْهَرِيّ وَغَيْره . فَمَعْنَى الْكَلِمَة إِذًا التَّنْحِيَة وَالْإِزَالَة ; وَذَلِكَ لَا يَكُون فِي حَقّ النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ إِلَّا بِهَلَاكِهِ وَمَوْته . قَالَ الْهَرَوِيّ : أَرَادَ لَيَعْتَانُونَكَ بِعُيُونِهِمْ فَيُزِيلُونَك عَنْ مَقَامك الَّذِي أَقَامَك اللَّه فِيهِ عَدَاوَة لَك . وَقَالَ اِبْن عَبَّاس : يَنْفُذُونَك بِأَبْصَارِهِمْ ; يُقَال : زَلَقَ السَّهْم وَزَهَقَ إِذَا نَفَذَ ; وَهُوَ قَوْل مُجَاهِد . أَيْ يَنْفُذُونَك مِنْ شِدَّة نَظَرِهِمْ . وَقَالَ الْكَلْبِيّ : يَصْرَعُونَك . وَعَنْهُ أَيْضًا وَالسُّدِّيّ وَسَعِيد بْن جُبَيْر : يَصْرِفُونَك عَمَّا أَنْتَ عَلَيْهِ مِنْ تَبْلِيغ الرِّسَالَة . وَقَالَ الْعَوْفِيّ : يَرْمُونَك . وَقَالَ الْمُؤَرِّج : يُزِيلُونَك . وَقَالَ النَّضْر بْن شُمَيْلٍ وَالْأَخْفَش : يَفْتِنُونَك . وَقَالَ عَبْد الْعَزِيز بْن يَحْيَى : يَنْظُرُونَ إِلَيْك نَظَرًا شَزْرًا بِتَحْدِيقٍ شَدِيد . وَقَالَ اِبْن زَيْد : لَيَمَسُّونَك . وَقَالَ جَعْفَر الصَّادِق : لَيَأْكُلُونَك . وَقَالَ الْحَسَن وَابْن كَيْسَان : لَيَقْتُلُونَك . وَهَذَا كَمَا يُقَال : صَرَعَنِي بِطَرْفِهِ , وَقَتَلَنِي بِعَيْنِهِ . قَالَ الشَّاعِر : تَرْمِيك مُزْلَقَة الْعُيُون بِطَرْفِهَا وَتَكِلّ عَنْك نِصَال نَبْل الرَّامِي وَقَالَ آخَر : يَتَقَارَضُونَ إِذَا اِلْتَقَوْا فِي مَجْلِس نَظَرًا يُزِلّ مَوَاطِئَ الْأَقْدَام وَقِيلَ : الْمَعْنَى أَنَّهُمْ يَنْظُرُونَ إِلَيْك بِالْعَدَاوَةِ حَتَّى كَادُوا يُسْقِطُونَك . وَهَذَا كُلّه رَاجِع إِلَى مَا ذَكَرْنَا , وَأَنَّ الْمَعْنَى الْجَامِع : يُصِيبُونَك بِالْعَيْنِ . وَاَللَّه أَعْلَم .';
$t[52] = 'أَيْ وَمَا الْقُرْآن إِلَّا ذِكْر لِلْعَالَمِينَ . وَقِيلَ : أَيْ وَمَا مُحَمَّد إِلَّا ذِكْر لِلْعَالَمِينَ يَتَذَكَّرُونَ بِهِ . وَقِيلَ : مَعْنَاهُ شَرَف ; أَيْ الْقُرْآن . كَمَا قَالَ تَعَالَى : &quot; وَإِنَّهُ لَذِكْر لَك وَلِقَوْمِك &quot; [ الزُّخْرُف : 44 ] وَالنَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ شَرَف لِلْعَالَمِينَ أَيْضًا . شَرُفُوا بِاتِّبَاعِهِ وَالْإِيمَان بِهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ';
?>